(function (root) {
  root.ASVAB_BANK = root.ASVAB_BANK || {};
  root.ASVAB_BANK["MC"] = [{"id": "MC-0001", "source_number": 1558, "subtest": "MC", "stem": "An induction clutch works by ___________.", "options": {"A": "magnetism", "B": "pneumatics", "C": "hydraulics", "D": "friction"}, "answer": "A", "answer_raw": "A", "explanation": "An induction clutch is a magnetic clutch.", "figure": null, "passage_id": null, "topics": ["hydraulics", "friction"], "difficulty": 1, "flags": [], "page": 504, "excluded": false}, {"id": "MC-0002", "source_number": 1559, "subtest": "MC", "stem": "If a first class lever with a resistance arm measuring 2 feet and an effort arm measuring 8 feet\nare being used, what's the mechanical advantage?", "options": {"A": "2", "B": "4", "C": "6", "D": "1"}, "answer": "B", "answer_raw": "B", "explanation": "Mechanical advantage can be calculated as Length of Effort Arm \u00f7 Length of Resistance Arm.\nMA = 8 \u00f7 2 = 4.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "levers"], "difficulty": 2, "flags": [], "page": 504, "excluded": false}, {"id": "MC-0003", "source_number": 1560, "subtest": "MC", "stem": "The bottoms of four boxes are shown above. The boxes all have the same volume.\nIf postal regulations state that the sides of a box must meet a minimum height, which box is\nmost likely to be too short to go through the mail?", "options": {"A": "NO. 4", "B": "NO. 2", "C": "NO. 1", "D": "NO. 3"}, "answer": "D", "answer_raw": "D", "explanation": "The box with the largest area on the bottom will have the shortest sides.\nIf length \u00d7 width \u00d7 height = volume, and all the boxes have equal volume, then the sides must\nbe shortest on the box with the largest area on the bottom.\nCalculate the area of each box bottom:\nNO. 1 = 20 square inches;\nNO. 2 = 35 square inches;\nNO. 3 = 48 square inches; and\nNO. 4 = 27 square inches.\nNO. 3, which has the largest area, will have the shortest sides.", "figure": "assets/figures/q1560.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 504, "excluded": false}, {"id": "MC-0004", "source_number": 1561, "subtest": "MC", "stem": "Looking at the figure above, when Cat B lands on the seesaw, Cat A will __________.", "options": {"A": "remain stationary", "B": "hit the ground hard", "C": "rise in the air quickly", "D": "enter the stratosphere"}, "answer": "C", "answer_raw": "C", "explanation": "Cat B landing on the seesaw will propel Cat A into the air.", "figure": "assets/figures/q1561.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 1, "flags": ["has_figure"], "page": 505, "excluded": false}, {"id": "MC-0005", "source_number": 1562, "subtest": "MC", "stem": "Air weighs about 15 psi.\nWhat's the amount of pressure (force) exerted on the top of your head, given a surface area of\n\n\n\n24 inches?", "options": {"A": "360 pounds", "B": "625 pounds", "C": "5/8 pound", "D": "180 pounds"}, "answer": "A", "answer_raw": "A", "explanation": "Power equals force divided by area in square inches (P = F/A).\nThis formula can also be stated as F = A \u00d7 P.\nSubstitute the known quantities.\nF = 15 \u00d7 24 = 360 pounds.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": [], "page": 506, "excluded": false}, {"id": "MC-0006", "source_number": 1563, "subtest": "MC", "stem": "The force produced when a boxer's hand hits a heavy bag and \"bounces\" off it is called\n__________.", "options": {"A": "static electricity", "B": "magnetism", "C": "recoil", "D": "gravity"}, "answer": "C", "answer_raw": "C", "explanation": "Recoil occurs when an object producing a force is kicked back.", "figure": null, "passage_id": null, "topics": ["springs", "force_pressure"], "difficulty": 2, "flags": [], "page": 507, "excluded": false}, {"id": "MC-0007", "source_number": 1564, "subtest": "MC", "stem": "In the figure above, if Gear 1 has 25 teeth and Gear 2 has 15 teeth, how many revolutions does\nGear 2 make for every 10 revolutions Gear 1 makes?", "options": {"A": "about 162/3", "B": "12", "C": "about 1/3 more", "D": "about 20"}, "answer": "A", "answer_raw": "A", "explanation": "To determine the answer, multiply the number of teeth Gear 1 has D and the number of\nrevolutions it makes (R).\nDivide that number by the number of teeth Gear 2 has D to determine the number of revolutions\nGear 2 makes (r).\nBecause the gears are proportional, this formula will show you the ratio of teeth to revolutions.\nr = DR/d\nr = (25 \u00d7 10)/15\nr = 250/15, or 1610/15, or 162/3", "figure": "assets/figures/q1564.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 2, "flags": ["has_figure"], "page": 507, "excluded": false}, {"id": "MC-0008", "source_number": 1565, "subtest": "MC", "stem": "A cubic foot of water weighs about 62.5 pounds.\nIf an aquarium is 18 feet long, 10 feet deep, and 12 feet wide, what's the approximate pounds-\nper-square-inch pressure (psi) on the bottom of the tank?", "options": {"A": "2 psi", "B": "4 psi", "C": "5 psi", "D": "7 psi"}, "answer": "B", "answer_raw": "B", "explanation": "You can determine the pressure of all that water by multiplying the volume of the aquarium by\nthe weight of the water. Volume = lwh.\nThe bottom of the tank is 18 feet long by 12 feet wide by 10 feet high for a total volume of 2,160\ncubic feet (18 \u00d7 12 \u00d7 10).\nA cubic foot of water weighs approximately 62.5 pounds.\n2,160 \u00d7 62.5 gives an approximate pressure on the bottom of the tank of about 135,000 pounds\nover the entire surface area.\nThe surface area of the bottom of the tank is length \u00d7 width.\n216 inches (18 feet \u00d7 12) \u00d7 144 inches (12 feet \u00d7 12) = 31,104.\nDividing the pressure of 135,000 by the number of square inches of surface area gives an\napproximate PSI of 4.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": [], "page": 509, "excluded": false}, {"id": "MC-0009", "source_number": 1566, "subtest": "MC", "stem": "Springs used in machines are usually made of __________.", "options": {"A": "plastic", "B": "bronze", "C": "nylon fiber", "D": "steel"}, "answer": "D", "answer_raw": "D", "explanation": "Machine springs are usually made of steel although sometimes they're made of brass or other\nmetal alloys.", "figure": null, "passage_id": null, "topics": ["springs"], "difficulty": 1, "flags": [], "page": 509, "excluded": false}, {"id": "MC-0010", "source_number": 1567, "subtest": "MC", "stem": "A clutch is a type of __________.", "options": {"A": "universal joint", "B": "coupling", "C": "gear differential", "D": "cam follower"}, "answer": "B", "answer_raw": "B", "explanation": "Clutches connect and disconnect parts, so they're a type of coupling.", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": [], "page": 509, "excluded": false}, {"id": "MC-0011", "source_number": 1568, "subtest": "MC", "stem": "When Cam A completes one revolution, the lever will touch the contact point __________.", "options": {"A": "once", "B": "never", "C": "four times", "D": "twice"}, "answer": "D", "answer_raw": "D", "explanation": "When the high point of the cam connects with the lever arm, the lever arm will touch the contact\npoint.\nTwo high points on the cam mean the lever arm will touch the contact point twice with each\nrevolution of the cam.", "figure": "assets/figures/q1568.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 1, "flags": ["has_figure"], "page": 510, "excluded": false}, {"id": "MC-0012", "source_number": 1569, "subtest": "MC", "stem": "A single block-and-fall is called a __________.", "options": {"A": "fixed pulley", "B": "gun tackle", "C": "runner", "D": "sheave"}, "answer": "C", "answer_raw": "C", "explanation": "A single block-and-fall is called a runner.", "figure": null, "passage_id": null, "topics": ["pulleys"], "difficulty": 2, "flags": [], "page": 510, "excluded": false}, {"id": "MC-0013", "source_number": 1570, "subtest": "MC", "stem": "In the figure above, if the fulcrum supporting the lever is moved closer to the cat, the cat will be\n__________.", "options": {"A": "easier to lift and will move higher", "B": "harder to lift but will move higher", "C": "easier to lift but will not move as high", "D": "harder to lift and will not move as high"}, "answer": "C", "answer_raw": "C", "explanation": "If the fulcrum is moved closer to the cat, the length of the effort arm of the lever will be\nincreased, making the cat easier to raise, but the height to which the cat can be raised will be\nreduced.", "figure": "assets/figures/q1570.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 2, "flags": ["has_figure"], "page": 511, "excluded": false}, {"id": "MC-0014", "source_number": 1571, "subtest": "MC", "stem": "The mechanical advantage of the block-and-tackle arrangement shown above is __________.", "options": {"A": "2", "B": "4", "C": "6", "D": "1"}, "answer": "A", "answer_raw": "A", "explanation": "Because this block-and-tackle arrangement merely changes the direction of the pull, it has a\nmechanical advantage of only 2.", "figure": "assets/figures/q1571.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["has_figure"], "page": 511, "excluded": false}, {"id": "MC-0015", "source_number": 1572, "subtest": "MC", "stem": "In the figure above, if the cogs move up the track at the same rate of speed, Cog A will\n__________.", "options": {"A": "reach the top at the same time as Cog B", "B": "reach the top after Cog B", "C": "reach the top before Cog B", "D": "have greater difficulty staying on track"}, "answer": "C", "answer_raw": "C", "explanation": "The larger cog (Cog A) covers a greater linear distance in a given period of time.", "figure": "assets/figures/q1572.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 2, "flags": ["has_figure"], "page": 512, "excluded": false}, {"id": "MC-0016", "source_number": 1573, "subtest": "MC", "stem": "If a house key, a wooden spoon, a plastic hanger, and a wool jacket are all the same\ntemperature, which one feels the coldest?", "options": {"A": "key", "B": "spoon", "C": "hanger", "D": "jacket"}, "answer": "B", "answer_raw": "B", "explanation": "The key will feel coldest because metal is a better conductor than the other materials.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 513, "excluded": false}, {"id": "MC-0017", "source_number": 1574, "subtest": "MC", "stem": "In the figure above, assume the valves are all closed.\nTo fill the tank, but to prevent it from filling entirely, which valves should be open?", "options": {"A": "1 and 2 only", "B": "1, 2, and 3 only", "C": "1, 2, and 4 only", "D": "1, 2, 3, and 5 only"}, "answer": "D", "answer_raw": "D", "explanation": "Opening Valves 1 and 2 allows water to enter the tank.\nOpening Valves 3 and 5 prevents water from filling the tank entirely.\nOpening Valve 4 allows water to leave the tank.", "figure": "assets/figures/q1574.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 514, "excluded": false}, {"id": "MC-0018", "source_number": 1575, "subtest": "MC", "stem": "If Gear A is turned to the left __________.", "options": {"A": "Gear B turns to the right and Gear C turns to the left.", "B": "Gear B turns to the left and Gear C turns to the left.", "C": "Gear B turns to the right and Gear C turns to the right.", "D": "Gear B turns to the left and Gear C turns to the right."}, "answer": "A", "answer_raw": "A", "explanation": "Gears with their teeth together in mesh turn in opposite directions.\n\n\n\nGear A turns Gear B in the opposite direction (right), and Gear B turns Gear C in the opposite\ndirection (left).", "figure": "assets/figures/q1575.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 515, "excluded": false}, {"id": "MC-0019", "source_number": 1576, "subtest": "MC", "stem": "If Gear 1 moves in a clockwise direction, which other gears also turn clockwise?", "options": {"A": "3 and 5", "B": "3, 4, and 5", "C": "2 and 5", "D": "3 and 4"}, "answer": "A", "answer_raw": "A", "explanation": "Gears with their teeth together in mesh turn in opposite directions.\nGear 1 turns clockwise. Gear 2, in mesh with Gear 1, turns counterclockwise.\nGear 3, in mesh with Gear 2, turns clockwise.\nGear 4, in mesh with Gear 3, turns counterclockwise.\nGear 5, in mesh with Gear 2, turns clockwise.", "figure": "assets/figures/q1576.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 516, "excluded": false}, {"id": "MC-0020", "source_number": 1577, "subtest": "MC", "stem": "The pressure gauge in the figure above shows a reading of __________.", "options": {"A": "15.0", "B": "19.5", "C": "21.0", "D": "23.0"}, "answer": "C", "answer_raw": "C", "explanation": "The gauge shows a reading of 21.", "figure": "assets/figures/q1577.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": ["has_figure"], "page": 516, "excluded": false}, {"id": "MC-0021", "source_number": 1578, "subtest": "MC", "stem": "A way to determine the amount of power being used is to __________.", "options": {"A": "Multiply the amount of work done by the time it takes.", "B": "Multiply the distance covered by the time it takes to move a load.", "C": "Divide the amount of work done by 550 pounds per second.", "D": "Divide the amount of work done by the amount of time it takes."}, "answer": "D", "answer_raw": "D", "explanation": "The formula for determining power is Power = Work \u00f7 Time.", "figure": null, "passage_id": null, "topics": ["work_energy", "force_pressure"], "difficulty": 1, "flags": [], "page": 517, "excluded": false}, {"id": "MC-0022", "source_number": 1579, "subtest": "MC", "stem": "A wood tool, a silver tool, and a steel tool are placed in boiling water for cleaning.\nWhich tool gets the hottest?", "options": {"A": "steel", "B": "wood", "C": "silver", "D": "All three are equally hot."}, "answer": "C", "answer_raw": "C", "explanation": "Silver is the best conductor, so it becomes hottest.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 518, "excluded": false}, {"id": "MC-0023", "source_number": 1580, "subtest": "MC", "stem": "A runner is being used in the figure shown.\nHow much effort (disregard friction, wind resistance, and the weight of the pulley and the rope)\nis using the cat lover lifting the 50-pound crate (with cat)?", "options": {"A": "50-pound effort", "B": "100-pound effort", "C": "25-pound effort", "D": "10-pound effort"}, "answer": "A", "answer_raw": "A", "explanation": "Stationary pulleys give no mechanical advantage, so effort equals the weight of the crate or 50\npounds.", "figure": "assets/figures/q1580.jpg", "passage_id": null, "topics": ["pulleys", "mechanical_advantage", "friction"], "difficulty": 2, "flags": ["has_figure"], "page": 518, "excluded": false}, {"id": "MC-0024", "source_number": 1581, "subtest": "MC", "stem": "In the figure above, at what point was the ball traveling most slowly?", "options": {"A": "A", "B": "B", "C": "C", "D": "D"}, "answer": "C", "answer_raw": "C", "explanation": "At the height of the arc, the ball has no upward momentum, so it goes the slowest at that point.", "figure": "assets/figures/q1581.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback", "has_figure"], "page": 520, "excluded": false}, {"id": "MC-0025", "source_number": 1582, "subtest": "MC", "stem": "In the figure above, which angle is braced most solidly?", "options": {"A": "A", "B": "B", "C": "C", "D": "All are braced equally solidly."}, "answer": "A", "answer_raw": "A", "explanation": "The brace on Angle A covers more area of the angle, so it's more solidly braced.", "figure": "assets/figures/q1582.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback", "has_figure"], "page": 520, "excluded": false}, {"id": "MC-0026", "source_number": 1583, "subtest": "MC", "stem": "A simple pulley gives a mechanical advantage of __________.", "options": {"A": "2", "B": "3", "C": "1", "D": "unknown"}, "answer": "C", "answer_raw": "C", "explanation": "A simple pulley gives no mechanical advantage, although it does make work easier by\nspreading out the work needed over several tries. So the mechanical advantage is 1.", "figure": null, "passage_id": null, "topics": ["pulleys", "mechanical_advantage"], "difficulty": 1, "flags": [], "page": 522, "excluded": false}, {"id": "MC-0027", "source_number": 1584, "subtest": "MC", "stem": "The baskets are balanced on the arm in the figure above. If cherries are removed from Basket\nB, to rebalance the arm __________.", "options": {"A": "The fulcrum will have to be moved to the right.", "B": "Basket B will have to be moved to the right.", "C": "Basket A will have to be moved to the left.", "D": "Basket A will have to be moved to the right."}, "answer": "D", "answer_raw": "D", "explanation": "Moving Basket A to the right counterbalances the loss of cherries from Basket B.", "figure": "assets/figures/q1584.jpg", "passage_id": null, "topics": ["levers", "center_of_gravity"], "difficulty": 2, "flags": ["has_figure"], "page": 522, "excluded": false}, {"id": "MC-0028", "source_number": 1585, "subtest": "MC", "stem": "If both Wheel A and Wheel B revolve at the same rate in the figure above, Wheel A will cover a\nlinear distance of 12 feet __________.", "options": {"A": "faster than Wheel B", "B": "slower than Wheel B", "C": "in about the same time as Wheel B", "D": "half as quickly as Wheel B"}, "answer": "A", "answer_raw": "A", "explanation": "Wheel B has to make more revolutions to cover the same ground as Wheel A, so it will cover\nthe distance more slowly.", "figure": "assets/figures/q1585.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 523, "excluded": false}, {"id": "MC-0029", "source_number": 1586, "subtest": "MC", "stem": "If a force of 200 pounds is exerted over an area of 10-square inches, what's the psi?", "options": {"A": "10", "B": "15", "C": "20", "D": "200"}, "answer": "C", "answer_raw": "C", "explanation": "You can calculate psi as Pressure = Force/Are\nA. So, in this problem, P = 200/10 = 20.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": [], "page": 525, "excluded": false}, {"id": "MC-0030", "source_number": 1587, "subtest": "MC", "stem": "In the figure above, if Cat A moves toward the middle of the seesaw to get a better look at the\nmouse, Cat B will __________.", "options": {"A": "remain stationary", "B": "move toward the ground", "C": "rise in the air", "D": "instigate a cat fight"}, "answer": "B", "answer_raw": "B", "explanation": "The Cat B will move towards the ground", "figure": "assets/figures/q1587.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 2, "flags": ["has_figure"], "page": 525, "excluded": false}, {"id": "MC-0031", "source_number": 1588, "subtest": "MC", "stem": "If a ramp measures 6 feet in length and 3 feet in height, an object weighing 200 pounds requires\nhow much effort to move using the ramp?", "options": {"A": "200 pounds", "B": "100 pounds", "C": "50 pounds", "D": "300 pounds"}, "answer": "B", "answer_raw": "B", "explanation": "The formula to determine mechanical advantage of an incline plane is Length of Ramp \u00f7 Height\nof Ramp = Weight of Object \u00f7 Effort.\nPlugging in the numbers gives you:\n6/3 = 200/E\n6E = 600\nE = 100", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": [], "page": 526, "excluded": false}, {"id": "MC-0032", "source_number": 1589, "subtest": "MC", "stem": "A micrometer is used to measure ___________.", "options": {"A": "small changes in temperature", "B": "changes in psi", "C": "thicknesses to a few thousandths of an inch", "D": "objects invisible to the unaided eye"}, "answer": "C", "answer_raw": "C", "explanation": "Micrometers measure very small but not microscopic objects.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 526, "excluded": false}, {"id": "MC-0033", "source_number": 1590, "subtest": "MC", "stem": "If a cat is removed from Side B of the seesaw, what happens to the cats on Side A?", "options": {"A": "The cat will never move from Side B until it's good and ready.", "B": "The cats on Side A will move up in the air.", "C": "The cats on Side A will move toward the ground.", "D": "Nothing will happen."}, "answer": "C", "answer_raw": "C", "explanation": "Reducing the weight on Side B (by removing the cat) will cause Side A to move toward the\nground.", "figure": "assets/figures/q1590.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 2, "flags": ["has_figure"], "page": 526, "excluded": false}, {"id": "MC-0034", "source_number": 1591, "subtest": "MC", "stem": "The force produced when two objects rub against each other is called __________.", "options": {"A": "gravity", "B": "recoil", "C": "magnetism", "D": "friction"}, "answer": "D", "answer_raw": "D", "explanation": "Objects rubbing together produce friction.", "figure": null, "passage_id": null, "topics": ["springs", "friction", "force_pressure"], "difficulty": 1, "flags": [], "page": 527, "excluded": false}, {"id": "MC-0035", "source_number": 1592, "subtest": "MC", "stem": "Normally, atmospheric pressure is approximately __________.", "options": {"A": "14.7 psi", "B": "23.2 psi", "C": "7.0 psi", "D": "10.1 psi"}, "answer": "A", "answer_raw": "A", "explanation": "\"Normal\" atmospheric pressure is 14.7 psi.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 527, "excluded": false}, {"id": "MC-0036", "source_number": 1593, "subtest": "MC", "stem": "For Gear A and Gear B to mesh properly in the figure above __________.", "options": {"A": "They must be the same size.", "B": "They must turn at different rates.", "C": "They must both turn in the same direction.", "D": "Their teeth must be of equal size."}, "answer": "D", "answer_raw": "D", "explanation": "Gears of unequal size can mesh properly as long as their teeth are of equal size.", "figure": "assets/figures/q1593.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 528, "excluded": false}, {"id": "MC-0037", "source_number": 1594, "subtest": "MC", "stem": "Torsion springs __________.", "options": {"A": "produce a direct pull", "B": "exert no pull", "C": "produce a twisting action", "D": "coil but do not uncoil"}, "answer": "C", "answer_raw": "C", "explanation": "Torsion springs coil or uncoil and produce a twisting action, not a direct pull.", "figure": null, "passage_id": null, "topics": ["springs"], "difficulty": 1, "flags": [], "page": 529, "excluded": false}, {"id": "MC-0038", "source_number": 1595, "subtest": "MC", "stem": "To move a 400-pound crate from the floor of a warehouse to the bed of a truck 4-feet off the\nground, the most efficient device to use is a __________.", "options": {"A": "lever", "B": "incline plane", "C": "fixed pulley", "D": "jackscrew"}, "answer": "B", "answer_raw": "B", "explanation": "To move a heavy object a few feet in height, the incline plane is the most efficient device (of\nthose listed) to use.", "figure": null, "passage_id": null, "topics": ["pulleys", "levers"], "difficulty": 2, "flags": [], "page": 529, "excluded": false}, {"id": "MC-0039", "source_number": 1596, "subtest": "MC", "stem": "Water in an engine can cause damage in winter weather because __________.", "options": {"A": "it can vaporize", "B": "water expands when it freezes", "C": "ice is heavier than water", "D": "cold water creates more steam than warm water"}, "answer": "B", "answer_raw": "B", "explanation": "Water expands when it freezes, possibly damaging engine components.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 529, "excluded": false}, {"id": "MC-0040", "source_number": 1597, "subtest": "MC", "stem": "The weight of the load is being carried on the backs of the two cats shown in the figure.\nWhich cat is carrying the most weight?", "options": {"A": "Cat A", "B": "Cat B", "C": "Both are carrying an equal amount of weight.", "D": "It can't be determined without more information."}, "answer": "A", "answer_raw": "A", "explanation": "The load is closer to Cat A, so he's carrying the greater portion of the weight.", "figure": "assets/figures/q1597.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": ["has_figure"], "page": 530, "excluded": false}, {"id": "MC-0041", "source_number": 1598, "subtest": "MC", "stem": "When the block-and-tackle arrangement shown in the figure above is used to lift a load, all the\nfollowing parts remain stationary EXCEPT __________.", "options": {"A": "the upper hook", "B": "the upper block", "C": "the lower block", "D": "none; all the parts move"}, "answer": "C", "answer_raw": "C", "explanation": "All the listed parts remain stationary except the lower block.", "figure": "assets/figures/q1598.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 3, "flags": ["has_figure"], "page": 530, "excluded": false}, {"id": "MC-0042", "source_number": 1599, "subtest": "MC", "stem": "In the figure shown above, what effort E must be applied to lift the cat?", "options": {"A": "7.0 pounds", "B": "9.0 pounds", "C": "21.0 pounds", "D": "10.5 pounds"}, "answer": "A", "answer_raw": "A", "explanation": "Apply the leverage formula: Length of Effort Arm divided by Length of Resistance Arm =\nResistance Force divided by Effort Force. Or:\n9 \u00f7 3 = 21 \u00f7 E (effort force)\n3 = 21 \u00f7 E\n3E = 21 \u00f7 E \u00d7 E\n3E = 21\n3E \u00f7 3 = 21 \u00f7 3\nE = 7", "figure": "assets/figures/q1599.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["has_figure"], "page": 531, "excluded": false}, {"id": "MC-0043", "source_number": 1600, "subtest": "MC", "stem": "In the figure above, for each complete revolution the cam makes, how many times will the valve\nopen?", "options": {"A": "1", "B": "6", "C": "3", "D": "2"}, "answer": "C", "answer_raw": "C", "explanation": "The valve will open each time a high point of the cam hits it.\nThe cam has three high points, so the valve will open three times per revolution.", "figure": "assets/figures/q1600.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 532, "excluded": false}, {"id": "MC-0044", "source_number": 1601, "subtest": "MC", "stem": "In the figure above, assume the valves are all open.\nWhich valves need to be closed for the tank to fill up completely?", "options": {"A": "3 and 4 only", "B": "3, 4, and 5", "C": "2, 3, and 4", "D": "4 only"}, "answer": "A", "answer_raw": "A", "explanation": "Closing only Valves 3 and 4 keeps the water from leaving the tank.", "figure": "assets/figures/q1601.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 533, "excluded": false}, {"id": "MC-0045", "source_number": 1602, "subtest": "MC", "stem": "If Gear A turns left in the figure above, Gear B __________.", "options": {"A": "won't turn", "B": "turns left", "C": "turns right", "D": "It can't be determined."}, "answer": "C", "answer_raw": "C", "explanation": "Gears in mesh always turn in opposite directions.", "figure": "assets/figures/q1602.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 534, "excluded": false}, {"id": "MC-0046", "source_number": 1603, "subtest": "MC", "stem": "If Gear 1 makes 10 complete clockwise revolutions per minute in the figure above, then\n__________.", "options": {"A": "Gear 2 makes 10 complete clockwise revolutions per minute.", "B": "Gear 2 makes 20 complete counterclockwise revolutions per minute.", "C": "Gear 2 makes 5 complete counterclockwise revolutions per minute.", "D": "Gear 3 keeps Gear 2 from making any revolutions."}, "answer": "B", "answer_raw": "B", "explanation": "If Gear 1 turns at 10 rpm, then Gear 2, which is half the size, turns twice as fast at a rate of 20\nrpm.", "figure": "assets/figures/q1603.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 535, "excluded": false}, {"id": "MC-0047", "source_number": 1604, "subtest": "MC", "stem": "For the fuel to travel from Reservoir A to Reservoir B, passing through Filters C and D on the\nway, which valves must be open?", "options": {"A": "1, 2, 4, and 8", "B": "1, 2, and 3", "C": "6, 7, and 8", "D": "4, 6, and 7"}, "answer": "A", "answer_raw": "A", "explanation": "Opening Valves 1, 2, 4, and 8 allows the fuel to travel through the filters.\nOpening Valves 1, 2, and 3 doesn't allow the fuel to travel through the filters.\nOpening Valves 6, 7, and 9 doesn't allow the fuel to travel through the filters.\nOpening Valves 4, 6, and 7 will allow fuel to travel through the filters but not to Reservoir B.", "figure": "assets/figures/q1604.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 536, "excluded": false}, {"id": "MC-0048", "source_number": 1605, "subtest": "MC", "stem": "A yellow flame on a gas furnace indicates __________.", "options": {"A": "Everything is fine.", "B": "The fuel-air mixture is too rich.", "C": "The fuel-air mixture is too lean.", "D": "The gas pressure is too low."}, "answer": "B", "answer_raw": "B", "explanation": "A yellow flame indicates too much fuel or not enough air.\nMore air should be allowed to enter and mix with the gas.\nThus, the fuel-air mixture is too rich.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 537, "excluded": false}, {"id": "MC-0049", "source_number": 1606, "subtest": "MC", "stem": "If a water tank on a toilet keeps overflowing, the problem is probably a ___________.", "options": {"A": "defective float", "B": "clogged pipe", "C": "crimped chain", "D": "improper seal"}, "answer": "A", "answer_raw": "A", "explanation": "The float measures the water level in the tank. If the tank overflows, the float is probably\ndefective.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 538, "excluded": false}, {"id": "MC-0050", "source_number": 1607, "subtest": "MC", "stem": "In the figure shown above, the board holds the weight of the cat. The board is placed on two\nidentical scales.\nEach scale reads ___________.", "options": {"A": "24", "B": "10", "C": "12", "D": "40"}, "answer": "C", "answer_raw": "C", "explanation": "The 20-pound cat and the 4-pound board weigh 24 pounds total or, divided by 2, 12 pounds per\nscale.", "figure": "assets/figures/q1607.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": ["has_figure"], "page": 538, "excluded": false}, {"id": "MC-0051", "source_number": 1608, "subtest": "MC", "stem": "Helical gears have ___________.", "options": {"A": "straight teeth", "B": "slanted teeth", "C": "teeth of unequal size", "D": "no advantage over spur gears"}, "answer": "B", "answer_raw": "B", "explanation": "The teeth of helical gears are slanted.", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": [], "page": 539, "excluded": false}, {"id": "MC-0052", "source_number": 1609, "subtest": "MC", "stem": "In the figure above, which pillar supports the greater load of the cat?", "options": {"A": "Pillar A", "B": "Pillar B", "C": "Both pillars support the cat equally.", "D": "It's impossible to determine from the information given."}, "answer": "B", "answer_raw": "B", "explanation": "The cat is closer to Pillar B, so Pillar B bears more weight.", "figure": "assets/figures/q1609.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": ["has_figure"], "page": 539, "excluded": false}, {"id": "MC-0053", "source_number": 1610, "subtest": "MC", "stem": "Wheel A has a diameter of 10 feet. Wheel B has a diameter of 8 feet.\nIf both wheels revolve at the same rate, Wheel B will cover a linear distance of 16 feet\n___________.", "options": {"A": "at the same time as Wheel A", "B": "more slowly than Wheel A", "C": "in twice the time as Wheel A", "D": "faster than Wheel A"}, "answer": "B", "answer_raw": "B", "explanation": "Wheel B has to make more revolutions than Wheel A to cover the same amount of distance, so\nit will go slower.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 540, "excluded": false}, {"id": "MC-0054", "source_number": 1611, "subtest": "MC", "stem": "What effort must be used to lift a 30-pound cat (see the figure above) using a first-class lever?\n(Don't include the weight of the lever in your calculations.)", "options": {"A": "10 pounds", "B": "15 pounds", "C": "50 pounds", "D": "5 pounds"}, "answer": "A", "answer_raw": "A", "explanation": "E stands for effort needed. 30 (weight of the cat) \u00d7 2 (length of resistance arm) = x \u00d7 6 (length of\neffort arm).\nDo a little multiplication, and you get 60 = 6x.\nTo isolate x, divide each side by 6:\n60 \u00f7 6 = 6x \u00f7 6, or 10 = x.", "figure": "assets/figures/q1611.jpg", "passage_id": null, "topics": ["levers", "mechanical_advantage", "force_pressure"], "difficulty": 2, "flags": ["has_figure"], "page": 541, "excluded": false}, {"id": "MC-0055", "source_number": 1612, "subtest": "MC", "stem": "What mechanical advantage does the block and tackle arrangement in the above figure give?", "options": {"A": "1", "B": "3", "C": "2", "D": "4"}, "answer": "A", "answer_raw": "A", "explanation": "A fixed, simple pulley gives no mechanical advantage, so its mechanical-advantage number is\n1.", "figure": "assets/figures/q1612.jpg", "passage_id": null, "topics": ["pulleys", "mechanical_advantage"], "difficulty": 1, "flags": ["has_figure"], "page": 542, "excluded": false}, {"id": "MC-0056", "source_number": 1613, "subtest": "MC", "stem": "If a ramp is 8-feet long and 4-feet high, how much effort is required to move a 400-pound object\nup the ramp?", "options": {"A": "35 pounds", "B": "150 pounds", "C": "800 pounds", "D": "200 pounds"}, "answer": "D", "answer_raw": "D", "explanation": "The formula to determine the mechanical advantage of an incline plane is Length of Ramp \u00f7\nHeight of Ramp = Weight of Object \u00f7 Effort.\n8 \u00f7 4 = 400 \u00f7 E\n8/4 = 400/E\n8E = 1,600\n8E/8 = 1,600/8\nE = 200", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": [], "page": 544, "excluded": false}, {"id": "MC-0057", "source_number": 1614, "subtest": "MC", "stem": "33,000 foot-pounds of work done in one minute is called ___________.", "options": {"A": "a job for an enlisted soldier", "B": "one horsepower", "C": "330 psi", "D": "meaningful force"}, "answer": "B", "answer_raw": "B", "explanation": "Scientists agree that 33,000 foot-pounds per minute is one horsepower.", "figure": null, "passage_id": null, "topics": ["work_energy", "force_pressure"], "difficulty": 2, "flags": [], "page": 544, "excluded": false}, {"id": "MC-0058", "source_number": 1615, "subtest": "MC", "stem": "A 130-pound woman is wearing shoes with high heels that measure 1-inch square.\nIf the woman is standing on one heel, what psi does the heel exert as it rests on the ground?\n(Disregard atmospheric pressure from your calculations.)", "options": {"A": "130", "B": "65", "C": "260", "D": "11"}, "answer": "A", "answer_raw": "A", "explanation": "Power = Force/Area.\n\n\n\nP = 130/1 = 130.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": [], "page": 544, "excluded": false}, {"id": "MC-0059", "source_number": 1616, "subtest": "MC", "stem": "The force that causes clothes from the dryer to stick together is called ___________.", "options": {"A": "gravity", "B": "magnetism", "C": "friction", "D": "static electricity"}, "answer": "D", "answer_raw": "D", "explanation": "Static electricity causes materials to \"stick\" together this way.", "figure": null, "passage_id": null, "topics": ["friction", "force_pressure"], "difficulty": 1, "flags": [], "page": 545, "excluded": false}, {"id": "MC-0060", "source_number": 1617, "subtest": "MC", "stem": "An aneroid barometer measures ___________.", "options": {"A": "atmospheric pressure", "B": "water pressure", "C": "hydraulic-fluid pressure", "D": "the ambient temperature"}, "answer": "A", "answer_raw": "A", "explanation": "An aneroid barometer measures atmospheric pressure.", "figure": null, "passage_id": null, "topics": ["hydraulics", "force_pressure"], "difficulty": 1, "flags": [], "page": 545, "excluded": false}, {"id": "MC-0061", "source_number": 1618, "subtest": "MC", "stem": "If Gear A is revolving in a clockwise manner, as seen in the figure above, Gear B ___________.", "options": {"A": "remains stationary", "B": "revolves in a clockwise manner", "C": "revolves in a counterclockwise manner", "D": "turns more slowly than Gear A"}, "answer": "C", "answer_raw": "C", "explanation": "Meshed gears always turn in opposite directions.", "figure": "assets/figures/q1618.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 2, "flags": ["has_figure"], "page": 545, "excluded": false}, {"id": "MC-0062", "source_number": 1619, "subtest": "MC", "stem": "Springs are used for the following purposes EXCEPT ___________.", "options": {"A": "to store energy for part of a mechanical cycle", "B": "to force a mechanical component to maintain contact with another component", "C": "to reduce shock or impact", "D": "to increase the weight of a mechanism"}, "answer": "D", "answer_raw": "D", "explanation": "Springs are used for all the listed purposes except to add weight.", "figure": null, "passage_id": null, "topics": ["force_pressure", "work_energy", "springs"], "difficulty": 2, "flags": [], "page": 547, "excluded": false}, {"id": "MC-0063", "source_number": 1620, "subtest": "MC", "stem": "The floats in Tubes A and B measure specific gravity.\nWhich tube contains the liquid with the higher specific gravity?", "options": {"A": "Tube A", "B": "Tube B", "C": "It can't be determined.", "D": "Both Tube A and Tube B have the same specific gravity."}, "answer": "B", "answer_raw": "B", "explanation": "Specific gravity is a comparison between the weight of a liquid and the weight of water.\nThe liquid with the higher specific gravity will have a float that rises higher.", "figure": "assets/figures/q1620.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 547, "excluded": false}, {"id": "MC-0064", "source_number": 1621, "subtest": "MC", "stem": "Universal joints are used to ___________.", "options": {"A": "connect ball bearings", "B": "fix two shafts so they don't pivot or rotate", "C": "connect shafts in a U-shape", "D": "couple two shafts set at different angles"}, "answer": "D", "answer_raw": "D", "explanation": "Universal joints are used to connect shafts that aren't in the same plane.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 549, "excluded": false}, {"id": "MC-0065", "source_number": 1622, "subtest": "MC", "stem": "The try-cock in the schematic above measures ___________.", "options": {"A": "temperature of water", "B": "pressure of water", "C": "pressure of steam buildup", "D": "level of water"}, "answer": "D", "answer_raw": "D", "explanation": "Try-cocks measure water level.\nWater seeks a level throughout a system, so in the schematic, the try-cock correctly indicates\nthe water level.", "figure": "assets/figures/q1622.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": ["has_figure"], "page": 549, "excluded": false}, {"id": "MC-0066", "source_number": 1623, "subtest": "MC", "stem": "The steel plate above is held in place by different machine screws, each indicated by different\nsymbols.\nHow many different types of machine screws have been used?", "options": {"A": "6", "B": "15", "C": "5", "D": "9"}, "answer": "A", "answer_raw": "A", "explanation": "There are 6 different symbols, so 6 different types of machine screws were used.", "figure": "assets/figures/q1623.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 550, "excluded": false}, {"id": "MC-0067", "source_number": 1624, "subtest": "MC", "stem": "The amount of force (F) needed to balance the lever in the figure above is most nearly\n___________.", "options": {"A": "15 pounds", "B": "13 pounds", "C": "7.5 pounds", "D": "20 pounds"}, "answer": "B", "answer_raw": "B", "explanation": "To determine the amount of force exerted by the cats, first multiply the length of the resistance\narm (as it applies to the cat) by the weight of each cat and add the products together.\nThe 10-pound cat is supported by the entire weight of the resistance arm, so 5 \u00d7 10 = 50.\nThe 5-pound cat is being supported by 3 feet of the resistance arm, so 3 \u00d7 5 = 15.\nAdd them up: 50 + 15 = 65.\nThis number is equal to the length of the resistance arm times effort (force) or 65 = 5F.\nTo isolate F, divide both sides by 5: 65 \u00f7 5 = 5F \u00f7 5 or 13 = F.", "figure": "assets/figures/q1624.jpg", "passage_id": null, "topics": ["levers", "force_pressure", "center_of_gravity"], "difficulty": 2, "flags": ["has_figure"], "page": 551, "excluded": false}, {"id": "MC-0068", "source_number": 1625, "subtest": "MC", "stem": "With one complete revolution of the cable winch shown above, the load will move __________.", "options": {"A": "12 inches", "B": "6 inches", "C": "24 inches", "D": "36 inches"}, "answer": "C", "answer_raw": "C", "explanation": "One revolution of the winch will move the weight 24 inches, the circumference of the winch\ndrum.", "figure": "assets/figures/q1625.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": ["has_figure"], "page": 551, "excluded": false}, {"id": "MC-0069", "source_number": 1626, "subtest": "MC", "stem": "In the figure above, assume the valves are all closed.\nWhich valves need to be open to fill the tank entirely?", "options": {"A": "1 and 2 only", "B": "1 only", "C": "1, 2, and 3", "D": "2 only"}, "answer": "A", "answer_raw": "A", "explanation": "Valves 1 and 2 need to be open to fill the tank.", "figure": "assets/figures/q1626.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 552, "excluded": false}, {"id": "MC-0070", "source_number": 1627, "subtest": "MC", "stem": "If Gear 1 in the figure above makes 10 complete clockwise revolutions per minute, then\n__________.", "options": {"A": "Gear 2 makes 2 clockwise revolutions per minute.", "B": "Gear 3 makes 8 clockwise revolutions per minute.", "C": "Gear 3 makes 30 clockwise revolutions per minute.", "D": "Gear 3 makes 9 counterclockwise revolutions per minute."}, "answer": "B", "answer_raw": "B", "explanation": "Gear 1 makes 10 clockwise revolutions per minute.\nGear 2, which is half the size, makes 20 counterclockwise revolutions per minute. (The number\nof revolutions it makes is inversely proportional to its difference in size.)\nGear 2 is half the size of Gear 1, so to determine the number of revolutions it makes, multiply\nthe number of revolutions Gear 1 makes by the inverse of 1/2: 10 \u00d7 2/1 (or just 2) = 20.\nGear 3 is 2.5 times the size of Gear 2. In other words, it is 5/2 the size of Gear 2.\nTo determine the number of revolutions Gear 3 makes, multiply the inverse of 5/2 by the\nnumber of revolutions Gear 2 makes: 2/5 \u00d7 20.\nThis can be stated as 20/1 (the number of revolutions Gear 2 makes per minute) \u00d7 2/5 (the\nfraction of revolutions Gear 3 makes) = 40/5 or 8 revolutions per minute.", "figure": "assets/figures/q1627.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 553, "excluded": false}, {"id": "MC-0071", "source_number": 1628, "subtest": "MC", "stem": "A gear and pinion have a ratio of 4 to 1.\nIf the gear makes 200 revolutions per minute, the speed of the pinion is __________.", "options": {"A": "50 rpm", "B": "800 rpm", "C": "400 rpm", "D": "200 rpm"}, "answer": "B", "answer_raw": "B", "explanation": "The pinion turns 4 times as often as the gear: 4 \u00d7 200 = 800.", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 2, "flags": [], "page": 554, "excluded": false}, {"id": "MC-0072", "source_number": 1629, "subtest": "MC", "stem": "The gas gauge in an auto relies on what mechanical device to measure the amount of gas in\nthe tank?", "options": {"A": "ball and cock", "B": "automatic valve", "C": "float", "D": "mechanical switch"}, "answer": "C", "answer_raw": "C", "explanation": "A float indicates the level of liquid in a container.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 555, "excluded": false}, {"id": "MC-0073", "source_number": 1630, "subtest": "MC", "stem": "Using a runner gives you a mechanical advantage of ___________.", "options": {"A": "4", "B": "2", "C": "3", "D": "1"}, "answer": "B", "answer_raw": "B", "explanation": "Using a runner (a single, moveable pulley) gives a mechanical advantage of 2.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": [], "page": 555, "excluded": false}, {"id": "MC-0074", "source_number": 1631, "subtest": "MC", "stem": "For the valve shown in the figure above to open once each second, the cam must revolve at a\nrate of __________.", "options": {"A": "6 rpm", "B": "10 rpm", "C": "15 rpm", "D": "3 rpm"}, "answer": "A", "answer_raw": "A", "explanation": "Because 60 seconds comprise a minute, the valve must open 60 times per minute.\nThe cam will open the valve 10 times per revolution, so 60 \u00f7 10 = 6.\nThe cam must make 6 revolutions per minute to raise the valve 60 times per minute.", "figure": "assets/figures/q1631.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 555, "excluded": false}, {"id": "MC-0075", "source_number": 1632, "subtest": "MC", "stem": "The figure above represents a water tank.\nWhich of the following statements is not true?", "options": {"A": "If Valves 1 and 2 are open and Valves 3, 4, and 5 are closed, the tank will eventually overflow.", "B": "If all valves are open, the water remains at a constant level as long as the rate of intake is equal to the rate of discharge.", "C": "Water in the tank will rise if Valves 1 and 2 are open and Valves 3 and 4 are closed.", "D": "The tank will empty entirely if Valves 1 and 2 are closed and Valves 4 and 5 are open."}, "answer": "D", "answer_raw": "D", "explanation": "Because Valve 4 is above the bottom of the tank, some water will remain in the tank below the\nlevel of the valve, so the tank will never be completely empty.", "figure": "assets/figures/q1632.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback", "has_figure"], "page": 556, "excluded": false}, {"id": "MC-0076", "source_number": 1633, "subtest": "MC", "stem": "Heat is a form of ___________.", "options": {"A": "calories", "B": "energy", "C": "beneficence", "D": "motion"}, "answer": "B", "answer_raw": "B", "explanation": "Heat is a form of energy - Calories measure heat, beneficence is an attitude or emotion, and\nmotion is something that can cause heat.", "figure": null, "passage_id": null, "topics": ["work_energy"], "difficulty": 1, "flags": [], "page": 558, "excluded": false}, {"id": "MC-0077", "source_number": 1634, "subtest": "MC", "stem": "The lift caused by an aircraft's wings is primarily due to ___________.", "options": {"A": "a decrease in pressure on the upper side of the wing (A)", "B": "a decrease in pressure on the bottom side of the wing B", "C": "a vacuum created under the wing at point B", "D": "an increase in pressure on the upper side of the wing (A)"}, "answer": "A", "answer_raw": "A", "explanation": "When oncoming air meets the leading edge of the airfoil (wing), some of it goes over the top of\n\n\n\nthe airfoil and some of it flows underneath.\nThe air flowing over the top of the wing has to go further than the air underneath, because it\nmust join together again with the air that flowed under the wing at the far (back) side of the wing\n- physical laws act together to prevent or minimize vacuums in most cases.", "figure": "assets/figures/q1634.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": ["has_figure"], "page": 558, "excluded": false}, {"id": "MC-0078", "source_number": 1635, "subtest": "MC", "stem": "Pliers are an example of a ___________.", "options": {"A": "first-class lever", "B": "second-class lever", "C": "third-class lever", "D": "fourth-class lever"}, "answer": "A", "answer_raw": "A", "explanation": "Pliers are an example of a first-class lever because the fulcrum is positioned between the effort\n(where your hand grips the pliers) and the load (the object that is being held or squeezed by the\npliers).", "figure": "assets/figures/q1635.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 1, "flags": ["has_figure"], "page": 559, "excluded": false}, {"id": "MC-0079", "source_number": 1636, "subtest": "MC", "stem": "The wheels below are connected by a belt as shown.\nIf the larger wheel makes two revolutions, how many revolutions will the smaller wheel make?", "options": {"A": "Less than one", "B": "One", "C": "Two", "D": "More than two"}, "answer": "D", "answer_raw": "D", "explanation": "We are not told the sizes of the two wheels, but we can see that one is larger than the other.\nIf the two wheels are connected by a belt, the small wheel will be forced to turn fester and\ncomplete more turns than the larger wheel.", "figure": "assets/figures/q1636.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 559, "excluded": false}, {"id": "MC-0080", "source_number": 1638, "subtest": "MC", "stem": "If the wheel on the left turns clockwise, which way will the wheel on the right turn?", "options": {"A": "Clockwise", "B": "Counterclockwise", "C": "Counter-counterclockwise", "D": "Unable to tell from the information given"}, "answer": "B", "answer_raw": "B", "explanation": "If the wheel on the left turns clockwise, the wheel on the right will turn counterclockwise.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 560, "excluded": false}, {"id": "MC-0081", "source_number": 1639, "subtest": "MC", "stem": "How can a gear system derive the greatest amount of mechanical advantage when a seven-\ntooth gear drives a ___________?", "options": {"A": "29-tooth gear", "B": "5-toothgear", "C": "24-tooth gear", "D": "17-tooth gear"}, "answer": "A", "answer_raw": "A", "explanation": "The greater the difference between the number of teeth of the two meshed gears, the greater\nthe torque or mechanical advantage.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "gears"], "difficulty": 2, "flags": [], "page": 560, "excluded": false}, {"id": "MC-0082", "source_number": 1640, "subtest": "MC", "stem": "An above-ground suburban water tank holds 540 gallons of water when full.\nIf the tank starts out full and is drained at a rate of 60 gallons per minute, how many seconds\nwill it take to empty out halfway?", "options": {"A": "54", "B": "240", "C": "270", "D": "480"}, "answer": "C", "answer_raw": "C", "explanation": "540 gallons divided by 60 gallons a minute means that it takes nine minutes to drain the tank\ncompletely.\nHalf of that time is 4.5 minutes; 4.5 multiplied by 60 seconds equals 270 seconds.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 561, "excluded": false}, {"id": "MC-0083", "source_number": 1641, "subtest": "MC", "stem": "Which of the following is not a simple machine?", "options": {"A": "Lever", "B": "Inclined plane", "C": "Axe", "D": "Pulley"}, "answer": "C", "answer_raw": "C", "explanation": "An axe is a compound machine: the handle is a lever, and the head is two inclined planes (each\nside of the blade edge).", "figure": null, "passage_id": null, "topics": ["pulleys", "mechanical_advantage", "levers"], "difficulty": 1, "flags": [], "page": 561, "excluded": false}, {"id": "MC-0084", "source_number": 1642, "subtest": "MC", "stem": "If you want to hammer in a heavy nail, it might be a good idea to use a hammer with a\n__________.", "options": {"A": "lighter head", "B": "heavy head", "C": "longer handle", "D": "shorter handle"}, "answer": "C", "answer_raw": "C", "explanation": "A longer handle - a longer lever - allows the hammerhead to reach a higher speed, thereby\nproducing more striking force.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 561, "excluded": false}, {"id": "MC-0085", "source_number": 1643, "subtest": "MC", "stem": "If you drag a log across the road, one way to reduce the amount of force needed to pull it would\nbe to ___________.", "options": {"A": "use a thicker rope", "B": "pull harder", "C": "cross at an angle", "D": "lubricate the road"}, "answer": "D", "answer_raw": "D", "explanation": "If you drag a log across the road, one way to reduce the amount of force needed to pull it would\nbe to lubricate the road.\nTwo things contribute to the force needed to pull the log across the road: the weight (mass) of\nthe log itself, and the friction between the log and the road.\nLubricating the road will reduce the friction and therefore reduce the force needed to pull the log\nacross the road.", "figure": "assets/figures/q1643.jpg", "passage_id": null, "topics": ["friction", "force_pressure"], "difficulty": 2, "flags": ["has_figure"], "page": 562, "excluded": false}, {"id": "MC-0086", "source_number": 1644, "subtest": "MC", "stem": "Presume that Pulley C is rotating clockwise.\nWhat direction will Pulley A rotate?", "options": {"A": "Clockwise", "B": "Counterclockwise", "C": "Insufficient information to answer", "D": "Pulley A will not rotate"}, "answer": "A", "answer_raw": "A", "explanation": "By rotating clockwise. Pulley C will cause Pulley B to rotate counterclockwise, which will in turn\ncause Pulley A to rotate clockwise.", "figure": "assets/figures/q1644.jpg", "passage_id": null, "topics": ["pulleys"], "difficulty": 1, "flags": ["has_figure"], "page": 562, "excluded": false}, {"id": "MC-0087", "source_number": 1645, "subtest": "MC", "stem": "The rate at which work is done is called __________.", "options": {"A": "Power", "B": "Effort", "C": "Watts", "D": "Horsepower"}, "answer": "A", "answer_raw": "A", "explanation": "The English unit of power is foot pound per second. It takes 550 foot pounds to make 1\nhorsepower. The SI unit is the joule per second or watt. A horsepower is 746 watts. The rate at\nwhich work is done is called power.\nPower is work done per unit of time.", "figure": null, "passage_id": null, "topics": ["work_energy", "mechanical_advantage"], "difficulty": 1, "flags": [], "page": 563, "excluded": false}, {"id": "MC-0088", "source_number": 1646, "subtest": "MC", "stem": "Forces existing in pairs are sometimes called __________.", "options": {"A": "action and interaction", "B": "reaction and interaction", "C": "action and reaction", "D": "friction and gravity"}, "answer": "C", "answer_raw": "C", "explanation": "A force cannot be exerted unless there is something there to push back. Forces exist in pairs.\nFor every action there is a reaction.", "figure": null, "passage_id": null, "topics": ["friction", "force_pressure"], "difficulty": 1, "flags": [], "page": 564, "excluded": false}, {"id": "MC-0089", "source_number": 1647, "subtest": "MC", "stem": "When forces act in pairs they are ___________.", "options": {"A": "equal in magnitude and opposite in direction", "B": "equal in magnitude and in the same direction", "C": "equal in magnitude", "D": "unequal in magnitude"}, "answer": "A", "answer_raw": "A", "explanation": "Since it is impossible to have one force unless it acts as one of a pair of forces, it means that\nthese forces must be equal in magnitude and opposite in direction.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 564, "excluded": false}, {"id": "MC-0090", "source_number": 1648, "subtest": "MC", "stem": "Which pendulum takes less time to make one complete back-and-forth swing?", "options": {"A": "X", "B": "Y", "C": "Both take the same amount of time.", "D": "There is not enough information to calculate the answer."}, "answer": "B", "answer_raw": "B", "explanation": "The length of time it takes for one all back and forth swing depends on the length of the string,\nnot the weight at the end of it.", "figure": "assets/figures/q1648.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 564, "excluded": false}, {"id": "MC-0091", "source_number": 1649, "subtest": "MC", "stem": "When you heat water that is confined in a closed container so that the steam cannot escape,\nthe pressure inside the container __________ and the temperature of the boiling water\n__________.", "options": {"A": "increases, decreases", "B": "increases, increases", "C": "decreases, decreases", "D": "decreases, increases"}, "answer": "B", "answer_raw": "B", "explanation": "Heating an enclosed container of boiling water increases the pressure of the water vapor\n(steam) inside the\n\n\n\ncontainer and increases the temperature of the water.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": [], "page": 565, "excluded": false}, {"id": "MC-0092", "source_number": 1650, "subtest": "MC", "stem": "If Block A, on which the lever is resting, is moved farther away from Block B __________.", "options": {"A": "it will be harder to lift Block B but it will go higher", "B": "it will be easier to lift Block B and it will go higher", "C": "it will be harder to lift Block B and it will not be lifted to the same height", "D": "it will be easier to lift Block B but it will not be lifted as high"}, "answer": "A", "answer_raw": "A", "explanation": "It will be harder to lift Block B but it will go higher.\nIf Block A under the beam serving as the lever is moved away from Block B on top of the lever\nbeam, the moment for the force exerted will increase, since the fulcrum is now closer to the\nforce; this will make Block B harder to lift.\nHowever, the height to which Block B on the end of the lever beam can be raised increases the\nfurther away Block A is moved from Block B.", "figure": "assets/figures/q1650.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 1, "flags": ["has_figure"], "page": 566, "excluded": false}, {"id": "MC-0093", "source_number": 1651, "subtest": "MC", "stem": "For two gears to mesh properly, they must __________.", "options": {"A": "rotate at the same speed", "B": "rotate in the same direction", "C": "have the same size teeth", "D": "have the same number of teeth"}, "answer": "C", "answer_raw": "C", "explanation": "For two gears to mesh properly, they must have the same size teeth.\nDifferent size gears will, by definition, rotate at different speeds even when their driving axles\nare moving at the same speed.\nAlso, interlocking or meshing gears rotate in opposite directions.", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": [], "page": 566, "excluded": false}, {"id": "MC-0094", "source_number": 1652, "subtest": "MC", "stem": "Kinetic energy is __________.", "options": {"A": "energy stored in chemicals, such as in a battery.", "B": "energy in moving electrons, as in an electric current.", "C": "energy in a moving object.", "D": "energy that can be released under certain conditions."}, "answer": "C", "answer_raw": "C", "explanation": "Kinetic energy is energy in a moving object.\nEnergy stored in chemicals, such as in a battery, is chemical energy; energy in moving\nelectrons, as in an electric current, is electric energy; and energy that can be released under\ncertain conditions is potential energy.", "figure": null, "passage_id": null, "topics": ["work_energy"], "difficulty": 1, "flags": [], "page": 566, "excluded": false}, {"id": "MC-0095", "source_number": 1653, "subtest": "MC", "stem": "The amount that a machine (simple or complex) multiplies your force or effort is called\n__________.", "options": {"A": "load distance", "B": "mechanical advantage", "C": "resistance effect", "D": "acceleration"}, "answer": "B", "answer_raw": "B", "explanation": "The amount that a machine (simple or complex) multiplies your force or effort is called\nmechanical advantage.\nLoad distance is how far the load moves when force is applied, and acceleration is the change\nin velocity or speed in a certain direction.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "force_pressure"], "difficulty": 1, "flags": [], "page": 567, "excluded": false}, {"id": "MC-0096", "source_number": 1654, "subtest": "MC", "stem": "The mechanical advantage of two meshing gears is calculated by dividing __________.", "options": {"A": "the number of teeth on the driving gear by the number of teeth on the driven gear.", "B": "the number of teeth on the driven gear by the number of teeth on the driving gear.", "C": "the number of teeth on the driving gear by the rotational speed.", "D": "the diameter of the driven gear by the number of teeth on the driving gear."}, "answer": "B", "answer_raw": "B", "explanation": "The mechanical advantage of two meshing gears is calculated by dividing the number of teeth\non the driven gear by the number of teeth on the driving gear.", "figure": null, "passage_id": null, "topics": ["gears", "mechanical_advantage"], "difficulty": 1, "flags": [], "page": 567, "excluded": false}, {"id": "MC-0097", "source_number": 1655, "subtest": "MC", "stem": "A compound machine is one in which __________.", "options": {"A": "a battery provides the force", "B": "one simple machine rotates around the second one", "C": "two or more simple machines work together", "D": "the mechanical advantages can be made to balance each other out"}, "answer": "C", "answer_raw": "C", "explanation": "A compound machine is one in which two or more simple machines work together.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "force_pressure", "center_of_gravity"], "difficulty": 1, "flags": [], "page": 567, "excluded": false}, {"id": "MC-0098", "source_number": 1656, "subtest": "MC", "stem": "When meshing or interlocking gears have different numbers of teeth, __________.", "options": {"A": "relative speeds depend on the speed of the drive aide for both", "B": "both gears will rotate at the same speed", "C": "the gear with more teeth will rotate fester than the gear with fewer teeth", "D": "the gear with fewer teeth will rotate fester than the gear with more teeth"}, "answer": "D", "answer_raw": "D", "explanation": "When meshing or interlocking gears have different numbers of teeth, the gear with fewer teeth\nwill rotate faster than the gear with more teeth.\nIf two gears are meshed, both cannot be driven or something will break - one must be driving\nand one must be driven.", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": [], "page": 568, "excluded": false}, {"id": "MC-0099", "source_number": 1657, "subtest": "MC", "stem": "Cranks are used to __________.", "options": {"A": "convert motion in a circle into motion in a straight line", "B": "convert motion in a straight line into motion in a circle", "C": "attach to rotating shafts to push separate pieces in a given direction", "D": "transfer power between rotating shafts of different diameters"}, "answer": "B", "answer_raw": "B", "explanation": "Cranks are used to convert motion in a straight line into motion in a circle, such as in a bicycle's\npedals and pistons in an automotive engine.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 568, "excluded": false}, {"id": "MC-0100", "source_number": 1658, "subtest": "MC", "stem": "Which of the other gears is moving in the opposite direction from Gear 1?", "options": {"A": "Gear 2", "B": "Gear 3", "C": "Both Gears 2 and 3", "D": "Neither Gear 2 or 3"}, "answer": "A", "answer_raw": "A", "explanation": "Meshed gears turn in opposite directions.\nGear 1 is turning clockwise; therefore.\nGear 2 is turning counterclockwise (the opposite direction from Gear 1) and Gear 3 is turning\nclockwise (the same direction as Gear l).", "figure": "assets/figures/q1658.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 568, "excluded": false}, {"id": "MC-0101", "source_number": 1659, "subtest": "MC", "stem": "Force is something that can change the velocity of an object by making it __________.", "options": {"A": "start or stop", "B": "speedup", "C": "slow down", "D": "all of the above"}, "answer": "D", "answer_raw": "D", "explanation": "Force is something that can change the velocity of an object by making it start or stop, speed\nup, or slow down.\nThis means that all the answers given are correct.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 569, "excluded": false}, {"id": "MC-0102", "source_number": 1660, "subtest": "MC", "stem": "The brakes on your car use the same force that stops your car if you just let it coast.\nThis force is called ___________.", "options": {"A": "velocity", "B": "gravity", "C": "friction", "D": "newton"}, "answer": "C", "answer_raw": "C", "explanation": "Friction is used to stop a car.\nThe brakes rub against the wheel drum or the disc to cause the car to stop.\nThis rubbing is creating friction.", "figure": null, "passage_id": null, "topics": ["force_pressure", "friction"], "difficulty": 2, "flags": [], "page": 570, "excluded": false}, {"id": "MC-0103", "source_number": 1661, "subtest": "MC", "stem": "As the central shaft in the illustration below spins faster in a clockwise direction, the balls\nlabeled A and B will ___________.", "options": {"A": "move outward and downward", "B": "move outward and upward", "C": "move up", "D": "move down"}, "answer": "B", "answer_raw": "B", "explanation": "Centrifugal force from the spinning shaft, regardless of direction, will cause the balls to move\noutward, away from the shaft; the tension on the strings holding them will result in the balls\nmoving upward.", "figure": "assets/figures/q1661.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 570, "excluded": false}, {"id": "MC-0104", "source_number": 1662, "subtest": "MC", "stem": "If you drop something, the force acting on it is ____________.", "options": {"A": "gravity", "B": "friction", "C": "elastic recoil", "D": "equilibrium"}, "answer": "A", "answer_raw": "A", "explanation": "Gravity is the force that pulls things down whenever they are dropped.\nIt is said that Isaac Newton \"discovered\" the concept of gravity as an identifiable force while\nsitting under an apple tree and the obvious happened.\nGravity is created by the mass of the earth.\nThe pull of gravity is much less (about one-sixth) on the moon than on earth.", "figure": null, "passage_id": null, "topics": ["springs", "friction", "force_pressure"], "difficulty": 1, "flags": [], "page": 572, "excluded": false}, {"id": "MC-0105", "source_number": 1663, "subtest": "MC", "stem": "In the illustration below, if Pulley A is rotating in the direction indicated, then Pulley C will\n__________.", "options": {"A": "rotate in the same direction as Pulley B", "B": "rotate in the same direction as Pulleys A and B", "C": "rotate in the opposite direction of Pulleys A and B", "D": "rotate in the same direction as Pulley A"}, "answer": "D", "answer_raw": "D", "explanation": "Pulley C will rotate in the same direction as Pulley A.\nPulley A causes Pulley B to rotate in the opposite direction from Pulley A, and Pulley B causes\nPulley C to rotate in the opposite direction from Pulley B.\nSince there are only two directions of rotation available.\nPulley C's direction of rotation is the same as Pulley A.", "figure": "assets/figures/q1663.jpg", "passage_id": null, "topics": ["pulleys"], "difficulty": 2, "flags": ["has_figure"], "page": 572, "excluded": false}, {"id": "MC-0106", "source_number": 1664, "subtest": "MC", "stem": "In the pulley system shown, which pulley will rotate the fastest?", "options": {"A": "Pulley A", "B": "Pulley B", "C": "Pulley C", "D": "They will all rotate at the same speed."}, "answer": "B", "answer_raw": "B", "explanation": "Pulley B will rotate the fastest. Just like meshing gears, the smaller the pulley in a system, the\nfester it rotates.", "figure": "assets/figures/q1664.jpg", "passage_id": null, "topics": ["pulleys"], "difficulty": 1, "flags": ["has_figure"], "page": 573, "excluded": false}, {"id": "MC-0107", "source_number": 1665, "subtest": "MC", "stem": "Weight is directly proportional to the acceleration due to ___________.", "options": {"A": "friction", "B": "elastic recoil", "C": "viscous drag", "D": "gravity"}, "answer": "D", "answer_raw": "D", "explanation": "Weight is not a fixed property of an object; it varies with location.\nYour weight is slightly less at the North Pole than it is at the equator.\nYour weight is much less on the moon than on earth.\nEverything weighs less where the acceleration due to gravity is smaller.\nWeight is directly proportional to local acceleration due to gravity.", "figure": null, "passage_id": null, "topics": ["springs", "friction"], "difficulty": 1, "flags": [], "page": 573, "excluded": false}, {"id": "MC-0108", "source_number": 1666, "subtest": "MC", "stem": "The force that acts in an upward direction on anything submerged in a liquid or a gas is called\n__________.", "options": {"A": "friction", "B": "viscous drag", "C": "gravity", "D": "buoyancy"}, "answer": "D", "answer_raw": "D", "explanation": "Buoyancy is the force that makes ships float and helium-filled balloons rise.\nThis means that the force that acts in an upward direction on anything submerged in a liquid or\na gas is called buoyancy.", "figure": null, "passage_id": null, "topics": ["friction", "force_pressure"], "difficulty": 2, "flags": [], "page": 574, "excluded": false}, {"id": "MC-0109", "source_number": 1667, "subtest": "MC", "stem": "In the illustration below, two 30-lbs blocks are attached to the ceiling using ropes, as shown.\nWhich of the following statements is true?", "options": {"A": "All the ropes are under equal amounts of tension.", "B": "The rope supporting Block A is under 2x the tension of the ropes holding Block B.", "C": "The ropes supporting Block B are under 1/3 of the tension of the rope holding Block A.", "D": "The rope holding Block A is under 1/3 of the tension of the ropes holding Block B."}, "answer": "C", "answer_raw": "C", "explanation": "There are three ropes supporting Block B; therefore, they are under 1/3 the tension as the rope\nsupporting Block A.", "figure": "assets/figures/q1667.jpg", "passage_id": null, "topics": ["springs"], "difficulty": 2, "flags": ["has_figure"], "page": 574, "excluded": false}, {"id": "MC-0110", "source_number": 1668, "subtest": "MC", "stem": "When the plug in the tube is removed, water will flow ___________.", "options": {"A": "into the tube", "B": "out of the tube", "C": "neither direction", "D": "impossible to tell"}, "answer": "A", "answer_raw": "A", "explanation": "When the plug is removed, water will flow into the tube to equalize the water level both inside\nand outside the tube.", "figure": "assets/figures/q1668.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback", "has_figure"], "page": 575, "excluded": false}, {"id": "MC-0111", "source_number": 1669, "subtest": "MC", "stem": "If an object is in equilibrium, it is said to be __________.", "options": {"A": "at rest", "B": "moving", "C": "at rest or moving at a constant speed and in a straight line", "D": "moving upward only"}, "answer": "C", "answer_raw": "C", "explanation": "An object in equilibrium may or may not be at rest.\n\n\n\nIf two or more forces act, their effects may eliminate each other.\nWhen this condition of equilibrium is reached, there is no net force and the velocity does not\nchange.\nEquilibrium is reached when the object is at rest or moving at a constant speed and in a straight\nline.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 576, "excluded": false}, {"id": "MC-0112", "source_number": 1670, "subtest": "MC", "stem": "In the figure, the angle b is important, since when it is __________.", "options": {"A": "0 degrees the entire force is dragging the box", "B": "90 degrees the entire force is lifting the box", "C": "both lifting and dragging between 10 degrees and 90 degrees", "D": "all of the above"}, "answer": "D", "answer_raw": "D", "explanation": "The angle of the rope determines if the box is being pulled along the floor or being lifted from\nthe floor.\nThat means it can be both lifted and pulled along at any angle that is more than 0 degrees and\nless than 90 degrees.", "figure": "assets/figures/q1670.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": ["has_figure"], "page": 577, "excluded": false}, {"id": "MC-0113", "source_number": 1671, "subtest": "MC", "stem": "A good example of a simple machine is a __________.", "options": {"A": "manually operated pencil sharpener", "B": "doorknob", "C": "light switch", "D": "all of the above"}, "answer": "D", "answer_raw": "D", "explanation": "Simple machines are devices that make work easier.\nSome examples of simple machines are levers, hydraulic jacks, loading ramps, vises, and\n\n\n\nmachines that spin - winches and gears.\nDoor knobs, light switches, and manually operated pencil sharpeners are also simple machines.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 577, "excluded": false}, {"id": "MC-0114", "source_number": 1672, "subtest": "MC", "stem": "Which weight exerts more pull on the horizontal bar from which both weights hang by strings as\nshown?", "options": {"A": "Block A", "B": "Block B", "C": "Both exert the same pull", "D": "Insufficient information to solve this problem"}, "answer": "A", "answer_raw": "A", "explanation": "The string holding the 10-lb. weight exerts more pull on the bar.\nThe fact that that string is longer does not change how much tension is on it due to the weight at\nits end.", "figure": "assets/figures/q1672.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 578, "excluded": false}, {"id": "MC-0115", "source_number": 1673, "subtest": "MC", "stem": "In the water system shown below, assume that the main tank starts empty and that all the\nvalves are closed.\nIn order for the tank to fill about halfway and keep that level, which valves have to be open?", "options": {"A": "Valves A, B, and C", "B": "Valves A, B, and D", "C": "Valves A, E, and B", "D": "Valves A, E, and C"}, "answer": "B", "answer_raw": "B", "explanation": "Valves A, B, and D must be open for the tank to fill halfway and maintain that level.\nWater flows in through Valve A (meaning that any choice not including Valve A is automatically\nincorrect), and flows out when the tank is half full through Valve B.\nHowever, for that water to leave the system. Valve D must also be open.", "figure": "assets/figures/q1673.jpg", "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback", "has_figure"], "page": 578, "excluded": false}, {"id": "MC-0116", "source_number": 1674, "subtest": "MC", "stem": "Work input is always more than work output because of __________.", "options": {"A": "gravity", "B": "buoyancy", "C": "friction", "D": "tension"}, "answer": "C", "answer_raw": "C", "explanation": "Efficiency is affected by friction. It is a ratio of how much effort went into a job compared to what\nwas produced or outputted.\nTherefore, work input is more than the work output. Friction accounts for the loss in efficiency.", "figure": null, "passage_id": null, "topics": ["springs", "friction"], "difficulty": 1, "flags": ["explanation_may_belong_to_next"], "page": 579, "excluded": false}, {"id": "MC-0117", "source_number": 1675, "subtest": "MC", "stem": "The ratio between work output and work input is called __________.", "options": {"A": "efficiency", "B": "work", "C": "leverage", "D": "mass"}, "answer": "A", "answer_raw": "A", "explanation": "In order to find out how well work was performed and how much effort was expended in getting\nthe job done, the term efficiency is used to describe the ratio of work input to work output.", "figure": null, "passage_id": null, "topics": ["levers"], "difficulty": 1, "flags": [], "page": 580, "excluded": false}, {"id": "MC-0118", "source_number": 1676, "subtest": "MC", "stem": "The amount of magnification that a machine produces is referred to as the __________.", "options": {"A": "effort arm", "B": "work", "C": "mechanical advantage", "D": "efficiency"}, "answer": "C", "answer_raw": "C", "explanation": "By using a machine, it is possible to multiply the amount of effort expended to get a job done.\nMechanical advantage is the amount of magnification, or the ratio of load to effort.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": [], "page": 580, "excluded": false}, {"id": "MC-0119", "source_number": 1677, "subtest": "MC", "stem": "A ramp is a device commonly used to aid in __________.", "options": {"A": "lifting", "B": "lowering weights", "C": "high-efficiency situations", "D": "loading"}, "answer": "A", "answer_raw": "A", "explanation": "A ramp is a device commonly used to aid in lifting.\nThe ramp is an inclined plane.\n\n\n\nThe work output of an inclined plane is the work that would have to be done to lift the load\ndirectly.\nThe work input is the actual force exerted in pushing the load up the ramp times the length of\nthe ramp.\nAn ideal mechanical advantage of an inclined plane is equal to its length divided by its height.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "force_pressure"], "difficulty": 1, "flags": [], "page": 580, "excluded": false}, {"id": "MC-0120", "source_number": 1678, "subtest": "MC", "stem": "A screw consists of a single continuous spiral wrapped around a __________.", "options": {"A": "piston", "B": "cylinder", "C": "helix", "D": "square"}, "answer": "B", "answer_raw": "B", "explanation": "A screw is a simple device. It has been used for centuries as a means of lifting water out of\nwells and over the banks of irrigation canals.\nA screw consists of a single continuous spiral wrapped around a cylinder.\nThe threads are cut into a rod in a spiral and make it possible to use the holding power of the\nscrew in fastening objects together.", "figure": null, "passage_id": null, "topics": ["hydraulics"], "difficulty": 1, "flags": [], "page": 581, "excluded": false}, {"id": "MC-0121", "source_number": 1679, "subtest": "MC", "stem": "If Pulley A is the driver and turns counterclockwise, which pulley will turn the slowest?", "options": {"A": "Pulley A", "B": "Pulley B", "C": "Pulley C", "D": "Pulley D"}, "answer": "D", "answer_raw": "D", "explanation": "The pulley that is the largest will turn most slowly.", "figure": "assets/figures/q1679.jpg", "passage_id": null, "topics": ["pulleys"], "difficulty": 1, "flags": ["has_figure"], "page": 581, "excluded": false}, {"id": "MC-0122", "source_number": 1680, "subtest": "MC", "stem": "The mechanical advantage of a winch is the ratio of the radius of the crank to the radius of the\n__________.", "options": {"A": "arm", "B": "lever", "C": "fulcrum", "D": "shaft"}, "answer": "D", "answer_raw": "D", "explanation": "The principle of a winch is not much different from that of a lever.\nSince the crank and the shaft turn together, the torque exerted by the effort (the force on the\nhandle) must be equal to the torque exerted by the load (the tension in the rope).\nThe mechanical advantage then is the ratio of the radius of the crank to the radius of the shaft.", "figure": null, "passage_id": null, "topics": ["levers", "mechanical_advantage"], "difficulty": 2, "flags": [], "page": 582, "excluded": false}, {"id": "MC-0123", "source_number": 1681, "subtest": "MC", "stem": "The ideal mechanical advantage of a gear is the ratio of the number of teeth in the load gear to\nthe number of teeth in the __________.", "options": {"A": "effort gear", "B": "loaded gear", "C": "lifting gear", "D": "spiral gear"}, "answer": "A", "answer_raw": "A", "explanation": "In mechanical devices, gears are used to change torque.\nThe ideal mechanical advantage of a gear is the ratio of the number of teeth in the load gear to\nthe number of teeth in the effort gear.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "gears", "force_pressure"], "difficulty": 2, "flags": [], "page": 582, "excluded": false}, {"id": "MC-0124", "source_number": 1682, "subtest": "MC", "stem": "Which mechanical components are typically used between a wheel and an axle to reduce\nfriction?", "options": {"A": "springs", "B": "hinges", "C": "bearings", "D": "levers"}, "answer": "C", "answer_raw": "C", "explanation": "A set of bearings is typically a set of small metal balls packed in a groove and lubricated with\ngrease or oil.\nThe wheel rubs against one side of each ball, and the axle rubs against the other side.\n\n\n\nThe net effect is that the wheel rolls much more easily.", "figure": null, "passage_id": null, "topics": ["springs", "levers", "friction"], "difficulty": 1, "flags": [], "page": 582, "excluded": false}, {"id": "MC-0125", "source_number": 1683, "subtest": "MC", "stem": "A block of steel has a density of 0.29 pounds per cubic inch.\nIf the block has dimensions of 1 inch by 1 inch by 3 inches, what is its weight?", "options": {"A": "0.29 pounds", "B": "0.58 pounds", "C": "0.87 pounds", "D": "1.0 pounds"}, "answer": "C", "answer_raw": "C", "explanation": "The volume of the block can be calculated by multiplying its length by its width by its height, or 1\ntimes 1 times 3, which equals 2 cubic inches.\nThe weight is the density multiplied by its volume, which is 3 cubic inches multiplied by 0.29\npounds per cubic inch, which equals 0.87 pounds.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 583, "excluded": false}, {"id": "MC-0126", "source_number": 1684, "subtest": "MC", "stem": "Which principle of mechanical motion is used in the design of a roller coaster?", "options": {"A": "momentum", "B": "friction", "C": "acceleration", "D": "all of the above"}, "answer": "D", "answer_raw": "D", "explanation": "Acceleration must be considered in designing the maximum rise of the first hill.\nMomentum must be considered to ensure the train gets back to the starting point, since it has\nno motor.\nFriction must be considered in the design of the braking system.", "figure": null, "passage_id": null, "topics": ["friction"], "difficulty": 1, "flags": [], "page": 583, "excluded": false}, {"id": "MC-0127", "source_number": 1685, "subtest": "MC", "stem": "Which term below best describes the OPPOSITE of an increase in speed?", "options": {"A": "rotation", "B": "deceleration", "C": "friction", "D": "velocity"}, "answer": "B", "answer_raw": "B", "explanation": "Deceleration means slowing down.", "figure": null, "passage_id": null, "topics": ["friction"], "difficulty": 1, "flags": [], "page": 583, "excluded": false}, {"id": "MC-0128", "source_number": 1686, "subtest": "MC", "stem": "A valve is used to perform which of the following functions?", "options": {"A": "increase the temperature of a liquid", "B": "control the flow of a liquid", "C": "aid evaporation of a liquid", "D": "decrease the density of a liquid"}, "answer": "B", "answer_raw": "B", "explanation": "Valves are placed in piping systems and can be opened or closed in order to control the flow of\nliquids or gasses.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 584, "excluded": false}, {"id": "MC-0129", "source_number": 1687, "subtest": "MC", "stem": "The sprocket on a bicycle is most similar to which of the simple mechanical devices listed\nbelow?", "options": {"A": "a gear", "B": "a spring", "C": "a lever", "D": "all of the above"}, "answer": "A", "answer_raw": "A", "explanation": "A bicycle sprocket is the classic example of a gear, which is defined as a toothed wheel or\ncylinder that meshes with a chain or with another toothed element to transfer energy or motion.", "figure": null, "passage_id": null, "topics": ["gears", "springs", "levers"], "difficulty": 1, "flags": [], "page": 584, "excluded": false}, {"id": "MC-0130", "source_number": 1688, "subtest": "MC", "stem": "A pump is typically used to accomplish which of the following tasks?", "options": {"A": "to clarify liquids", "B": "to separate liquids", "C": "to move liquids downhill", "D": "to move liquids uphill"}, "answer": "D", "answer_raw": "D", "explanation": "Pumps are not used to move liquids downhill because liquids will flow downhill by gravity.\nAlso, pumps do not separate or clarify liquids; instead, they agitate and mix liquids.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 584, "excluded": false}, {"id": "MC-0131", "source_number": 1689, "subtest": "MC", "stem": "In the diagram shown above, the spring is very stiff and can be stretched 1 inch by a pulling\nforce of 100 pounds.\nHow much force must be applied to the block in order to move the box 3.5 inches to the left?", "options": {"A": "150 pounds", "B": "250 pounds", "C": "350 pounds", "D": "450 pounds"}, "answer": "C", "answer_raw": "C", "explanation": "3.5 inches multiplied by 100 pounds per inch equals 350 pounds.", "figure": "assets/figures/q1689.jpg", "passage_id": null, "topics": ["springs", "force_pressure"], "difficulty": 2, "flags": ["has_figure"], "page": 584, "excluded": false}, {"id": "MC-0132", "source_number": 1690, "subtest": "MC", "stem": "A concrete beam has a maximum strength of 3,000 psi (pounds per square inch). In an\nexperiment, a 500- pound weight is placed in the center of the beam, and the stress in the beam\nis measured to be 1,000 psi.\nIf the stresses in the beam continue to increase at the same rate with added weight, how much\nadditional weight can be added to the same location on the beam before the beam will break?", "options": {"A": "500 pounds", "B": "1,000 pounds", "C": "1,500 pounds", "D": "3,000 pounds"}, "answer": "B", "answer_raw": "B", "explanation": "The first 500 pounds generated 1,000 psi of stress in the beam; therefore, 500 more pounds will\nincrease the\ntotal stress to 2,000 psi.\n\n\n\nAnother 500 pounds will increase the stress to 3,000 psi, which we are told is the maximum\nstrength of the beam.\nTherefore, the maximum additional load that can be applied to this beam before it breaks is\n1,000 pounds.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 3, "flags": [], "page": 585, "excluded": false}, {"id": "MC-0133", "source_number": 1691, "subtest": "MC", "stem": "An elevator is most similar to which of the following mechanical devices?", "options": {"A": "a spring", "B": "a hydraulic jet", "C": "a lever", "D": "a crane"}, "answer": "D", "answer_raw": "D", "explanation": "An elevator is simply a crane that raises and lowers people.", "figure": null, "passage_id": null, "topics": ["springs", "levers", "hydraulics"], "difficulty": 1, "flags": [], "page": 586, "excluded": false}, {"id": "MC-0134", "source_number": 1692, "subtest": "MC", "stem": "There are three beams that are each 10 feet long and all of the same size. One is made of\nwood, another of steel, and the third of concrete.\nIf identical loads are applied to these three beams, which of the following will occur?", "options": {"A": "The steel beam will deflect less than the wood beam.", "B": "The wood beam will deflect less than the concrete beam.", "C": "The wood beam will deflect less than the steel beam.", "D": "The concrete beam will deflect more than the other two."}, "answer": "A", "answer_raw": "A", "explanation": "The steel beam will deflect less than the wood beam.\nChoice \"The steel beam will deflect less than the wood beam\" is not correct since the concrete\nbeam will deflect less that the wood beam - concrete is stiffer than wood.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": [], "page": 586, "excluded": false}, {"id": "MC-0135", "source_number": 1693, "subtest": "MC", "stem": "What mechanical motion principle do the brakes in a car or on a bicycle use?", "options": {"A": "friction", "B": "centrifugal force", "C": "momentum", "D": "acceleration"}, "answer": "A", "answer_raw": "A", "explanation": "When the brakes are applied, the brake pads rub on the wheel and the frictional force of this\nrubbing slows down the vehicle.", "figure": null, "passage_id": null, "topics": ["friction", "force_pressure"], "difficulty": 1, "flags": [], "page": 586, "excluded": false}, {"id": "MC-0136", "source_number": 1694, "subtest": "MC", "stem": "The center of gravity of a baseball bat would be best described as __________.", "options": {"A": "near the skinny end", "B": "at the top", "C": "near the fat end", "D": "near the grip"}, "answer": "C", "answer_raw": "C", "explanation": "The center of gravity is the place on an object where there is equal weight on either side.", "figure": null, "passage_id": null, "topics": ["center_of_gravity"], "difficulty": 1, "flags": [], "page": 587, "excluded": false}, {"id": "MC-0137", "source_number": 1695, "subtest": "MC", "stem": "Which material is best suited for use as a boat anchor?", "options": {"A": "foam", "B": "metal", "C": "wood", "D": "glass"}, "answer": "B", "answer_raw": "B", "explanation": "Foam and wood float and would therefore make poor boat anchors.\nGlass is not strong enough to be used as a boat anchor.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 587, "excluded": false}, {"id": "MC-0138", "source_number": 1696, "subtest": "MC", "stem": "What would happen to a balloon full of air if you moved it from above a water surface to ten feet\nbelow the water surface?", "options": {"A": "The balloon would explode.", "B": "The volume of the balloon would decrease.", "C": "The volume of the balloon would increase.", "D": "The volume of the balloon would stay the same."}, "answer": "B", "answer_raw": "B", "explanation": "The volume of the balloon would decrease.\nThe pressure of the water would press inward on the balloon and cause it to shrink in volume.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 587, "excluded": false}, {"id": "MC-0139", "source_number": 1697, "subtest": "MC", "stem": "What is Newton's Third Law of Motion?", "options": {"A": "What goes up must come down.", "B": "For every action, there is an equal and opposite reaction.", "C": "Reactions are a result of large actions.", "D": "Mass cannot be destroyed."}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 587, "excluded": false}, {"id": "MC-0140", "source_number": 1698, "subtest": "MC", "stem": "The term equilibrium is defined as __________.", "options": {"A": "the state in which similar forces attract, causing a swell of movement in a single direction", "B": "the principle describing the notion that every action must have a reaction", "C": "the state in which opposing forces are balanced", "D": "the presence of motion in the present day which serves as a means of understanding movement as a whole"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["force_pressure", "center_of_gravity"], "difficulty": 1, "flags": [], "page": 588, "excluded": false}, {"id": "MC-0141", "source_number": 1699, "subtest": "MC", "stem": "What is the definition and the danger of recoil?", "options": {"A": "To recoil is to move quickly and efficiently, and it is not dangerous but desired.", "B": "To recoil is to feel revolted or disgusted, and it is dangerous because it creates job dissatisfaction.", "C": "To recoil is to respond in fear, and it is dangerous because engineers and workers need to remain in control. Losing control could result in serious injuries on the job.", "D": "Recoil is the concept of \"kicking back\" or leaping back after being released. It may be dangerous due to the possibility of injury upon having equipment \"leap back\" rapidly."}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["springs"], "difficulty": 1, "flags": [], "page": 588, "excluded": false}, {"id": "MC-0142", "source_number": 1700, "subtest": "MC", "stem": "Another word or phrase for false gravity is __________.", "options": {"A": "tension", "B": "friction", "C": "centrifugal force", "D": "Newton's Law"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["force_pressure", "springs", "friction"], "difficulty": 1, "flags": [], "page": 588, "excluded": false}, {"id": "MC-0143", "source_number": 1701, "subtest": "MC", "stem": "The phrase \"to adopt power\" means __________ when working.", "options": {"A": "to increase speed and efficiency to become your absolute best", "B": "to use a forceful tone when discussing work with a coworker", "C": "to focus energy on the lesser objects before moving on to larger instincts", "D": "to work authoritatively and with a slim, fit physique"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["work_energy", "force_pressure"], "difficulty": 1, "flags": [], "page": 588, "excluded": false}, {"id": "MC-0144", "source_number": 1702, "subtest": "MC", "stem": "A __________ should be applied if gear shafts are not parallel to one another.", "options": {"A": "shifting gear", "B": "third gear", "C": "bevel gear", "D": "stopping gear"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": [], "page": 589, "excluded": false}, {"id": "MC-0145", "source_number": 1703, "subtest": "MC", "stem": "What is the advantage of using wheels and axles?", "options": {"A": "Wheels and axles provide greater power, enabling workers to achieve greater results with less effort.", "B": "Wheels and axles are responsible for bearing the brunt of difficult lifting.", "C": "Wheels and axles are not beneficial.", "D": "Wheels and axles create a more effective conveyor belt effect."}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": [], "page": 589, "excluded": false}, {"id": "MC-0146", "source_number": 1704, "subtest": "MC", "stem": "What is the function of a vise in mechanical applications?", "options": {"A": "In mechanical applications, vises are used to arrest motion.", "B": "Vises are used to suspend quick movements, slowing the effects of conveyor belts.", "C": "In mechanical applications, vises are designed to assist movement.", "D": "Vises are designed to function as a source of stability, much like how legs function beneath a table."}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 589, "excluded": false}, {"id": "MC-0147", "source_number": 1705, "subtest": "MC", "stem": "A hydraulic jack performs the task of moving objects by __________.", "options": {"A": "utilizing oil; because oil cannot be compressed, pressure is placed upon the oil, resulting in a lifting motion", "B": "pressing together two interfacing parts to increase height", "C": "using a pulley system to lift items", "D": "using a corkscrew-like effect to function"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["springs", "pulleys", "hydraulics"], "difficulty": 1, "flags": [], "page": 589, "excluded": false}, {"id": "MC-0148", "source_number": 1706, "subtest": "MC", "stem": "Which of these statements about force is correct?", "options": {"A": "The amount of force required to move an object depends on the frictional forces between the object and its surroundings and must be calculated entirely based on individual situations.", "B": "The amount of force required to move an object does not depend on frictional conditions and cannot and will not exceed the weight of the object in question.", "C": "The amount of force required to move an object depends only on the weight of the object in question.", "D": "Force is best used in levered applications."}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["force_pressure", "levers", "friction"], "difficulty": 1, "flags": [], "page": 590, "excluded": false}, {"id": "MC-0149", "source_number": 1707, "subtest": "MC", "stem": "The purpose of mechanical comprehension is __________.", "options": {"A": "to inform workers on the proper use and function of machines", "B": "to determine how to adequately use mechanic's tools", "C": "to learn the use of various mechanisms", "D": "to describe the training undergone by car mechanics"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 590, "excluded": false}, {"id": "MC-0150", "source_number": 1708, "subtest": "MC", "stem": "What is the primary difference between distillation and evaporation?", "options": {"A": "Distillation separates or purifies liquids, while evaporation changes the form of a substance.", "B": "One is intentional in scope, while the other occurs during other practices.", "C": "Distillation involves the use of implements, while evaporation only requires heat.", "D": "Distillation and evaporation have no primary difference; they are the same process."}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 590, "excluded": false}, {"id": "MC-0151", "source_number": 1709, "subtest": "MC", "stem": "What is the state known as equilibrium?", "options": {"A": "Equilibrium describes the action of two similar forces coming together.", "B": "Equilibrium describes the state in which two different items possess equal force, resulting in balance.", "C": "Equilibrium describes the action of two opposing forces coming together in a crash.", "D": "Equilibrium describes the state created by the coming together of parallel forces."}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["force_pressure", "center_of_gravity"], "difficulty": 1, "flags": [], "page": 590, "excluded": false}, {"id": "MC-0152", "source_number": 1710, "subtest": "MC", "stem": "What purpose does an inclined plane serve?", "options": {"A": "An inclined plane is a tilted surface designed to aid in supporting or transporting a load.", "B": "Inclined planes are not useful implements and have been replaced by more effective methods of transportation.", "C": "Inclined planes are tilted surfaces designed to assist in suspension.", "D": "An inclined plane is intended to aid only in unloading merchandise."}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "force_pressure"], "difficulty": 1, "flags": [], "page": 590, "excluded": false}, {"id": "MC-0153", "source_number": 1711, "subtest": "MC", "stem": "If two workers are carrying a single load with the assistance of a board or plane, how should the\nload be placed to ensure an entirely equitable division of effort?", "options": {"A": "The load should be placed the same length from one side as the load is long; i.e. if the load is 3 feet wide, it should be placed 3 feet from the edge of the plane.", "B": "The load should be placed directly in the middle of the board or plane to ensure equal labor division between workers.", "C": "The cargo should be held directly, rather than placing strain on a board or plane.", "D": "The load should be placed closer to one end to prevent bowing of the plane."}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "force_pressure"], "difficulty": 2, "flags": [], "page": 591, "excluded": false}, {"id": "MC-0154", "source_number": 1712, "subtest": "MC", "stem": "A string of six gears exists, with each gear turning in conjunction with one another.\nWhich gears operate in the same rotation?", "options": {"A": "Gears 1, 2, and 3", "B": "Gears 1, 3, and 5", "C": "Gears 3, 4, and 5", "D": "Gears 2, 4, and 5"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 2, "flags": [], "page": 591, "excluded": false}, {"id": "MC-0155", "source_number": 1713, "subtest": "MC", "stem": "Which is the best description of centrifugal force?", "options": {"A": "the force responsible for the changes made to water during distillation.", "B": "the response of bodies with inertia to the straight-moving or curved behavior of their container.", "C": "the force by which bodies are propelled forward.", "D": "the relationship between two opposing forces."}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 591, "excluded": false}, {"id": "MC-0156", "source_number": 1714, "subtest": "MC", "stem": "What is the definition of a \"concurrent force\"?", "options": {"A": "A force system requiring concurrent movement.", "B": "A force system described as having multiple sources of force.", "C": "A system requiring all systems to pass through the same point.", "D": "A series of forces requiring simultaneous movement."}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 1, "flags": [], "page": 591, "excluded": false}, {"id": "MC-0157", "source_number": 1715, "subtest": "MC", "stem": "How does oil function in a machine with a series of moving parts?", "options": {"A": "Oil functions as a cleaning agent, allowing all moving parts to remain free of dirt and grime.", "B": "Oil functions as a source of lubrication, allowing moving parts to function as a single unit.", "C": "Oil serves as a fuel for moving parts in a machine.", "D": "Oil provides a source of power when paired with fire."}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["friction"], "difficulty": 1, "flags": [], "page": 592, "excluded": false}, {"id": "MC-0158", "source_number": 1716, "subtest": "MC", "stem": "Which of the following materials serves as a conductor?", "options": {"A": "Metal", "B": "Wood", "C": "Acrylic", "D": "Paper"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 592, "excluded": false}, {"id": "MC-0159", "source_number": 1717, "subtest": "MC", "stem": "To move an object across a surface, which system requires little input from the user, yet creates\nextreme force?", "options": {"A": "A conveyor belt, as those found in factories.", "B": "Any form of mechanical device.", "C": "wheel and axle system, as found in vehicles.", "D": "A pulley system, as might be found in warehouses and shipyards."}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["pulleys", "force_pressure"], "difficulty": 2, "flags": [], "page": 592, "excluded": false}, {"id": "MC-0160", "source_number": 1718, "subtest": "MC", "stem": "What determines the speed of a pulley system?", "options": {"A": "The material used as the belt (such as leather and rubber).", "B": "The size of the pulleys as a whole.", "C": "The size and ratio of all pulleys involved.", "D": "The length of the rope or belt used in the pulley system."}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["pulleys"], "difficulty": 1, "flags": [], "page": 592, "excluded": false}, {"id": "MC-0161", "source_number": 1719, "subtest": "MC", "stem": "Pulley systems require the synchronized movement of all pulleys.\nHow can pulleys escape this rule?", "options": {"A": "To violate this rule, pulley systems may be used in conjunction with gears.", "B": "This rule cannot be effectively violated.", "C": "To violate this rule, pulley system belts must be reversed.", "D": "Pulleys using twisted belts may move in opposing directions."}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["pulleys", "gears"], "difficulty": 1, "flags": [], "page": 593, "excluded": false}, {"id": "MC-0162", "source_number": 1720, "subtest": "MC", "stem": "What are the three components of a lever?", "options": {"A": "Resistance arm and effort arm", "B": "A point of origin and solid plane", "C": "A wide plane, fulcrum, and effort arm", "D": "Fulcrum, resistance arm, and effort arm"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["levers", "mechanical_advantage"], "difficulty": 1, "flags": [], "page": 593, "excluded": false}, {"id": "MC-0163", "source_number": 1721, "subtest": "MC", "stem": "What determines the speed of an output gear?", "options": {"A": "None of these (Gear speed is not capable of alteration.)", "B": "The size of gears.", "C": "The speed of the input gear and the ratio of the number of teeth on each gear.", "D": "The ratio of companion gears."}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": [], "page": 593, "excluded": false}, {"id": "MC-0164", "source_number": 1722, "subtest": "MC", "stem": "What are the potential functions of gear systems?", "options": {"A": "Gears may be used to change direction in machinery and can be used to increase speed.", "B": "Gears possess a single function: transmitting motion.", "C": "The potential functions of gears are: changes in direction, speed changes (both increases and decreases), and motion transmission.", "D": "Gears are primarily used for making changes in speed, but may also be used to instigate motion in machinery."}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": [], "page": 593, "excluded": false}, {"id": "MC-0165", "source_number": 1723, "subtest": "MC", "stem": "If a mechanical device is reported to have an advantage of 2, what does this mean?", "options": {"A": "The number \"2\" describes the effectiveness of the machine.", "B": "This means the device allows users to complete twice the amount of work with the same amount of effort used to complete a task without assistance.", "C": "The number refers to the speed of the device in question.", "D": "This means that the device requires twice the amount of effort to complete the same amount of work."}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": [], "page": 593, "excluded": false}, {"id": "MC-0166", "source_number": 1724, "subtest": "MC", "stem": "An \"inclined plane\" is a commonly used implement and has many applications, including\nhandicap access.\nWhat is the most common name for an inclined plane?", "options": {"A": "A pulley system", "B": "A lever", "C": "A ramp", "D": "A series of gears"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "pulleys", "levers"], "difficulty": 2, "flags": [], "page": 594, "excluded": false}, {"id": "MC-0167", "source_number": 1725, "subtest": "MC", "stem": "How can workers increase the mechanical advantage of pulley systems?", "options": {"A": "Using longer stretches of rope.", "B": "Using a higher platform for the load in need of lifting.", "C": "Using additional pulleys to further distribute weight.", "D": "Decreasing load size and weight."}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["pulleys", "mechanical_advantage", "force_pressure"], "difficulty": 1, "flags": [], "page": 594, "excluded": false}, {"id": "MC-0168", "source_number": 1726, "subtest": "MC", "stem": "The best definition for drag is __________.", "options": {"A": "a responsive force that affects the movement of an object through a fluid", "B": "a responsive force that only affects movement on a solid", "C": "a responsive force that only affects movement in air", "D": "the internal stretch force of a material"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["hydraulics", "force_pressure"], "difficulty": 1, "flags": [], "page": 594, "excluded": false}, {"id": "MC-0169", "source_number": 1727, "subtest": "MC", "stem": "Which of the following is an example of a Class 1 Lever?", "options": {"A": "Pliers", "B": "Wheelbarrow", "C": "Tongs", "D": "Stapler"}, "answer": "A", "answer_raw": "A", "explanation": "Pliers are an example of a Class 1 lever (actually 2 class 1 levers).\nWheelbarrow and stapler are class 2. Tongs are class 3.", "figure": "assets/figures/q1727.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 1, "flags": ["has_figure"], "page": 594, "excluded": false}, {"id": "MC-0170", "source_number": 1728, "subtest": "MC", "stem": "Which of the following will happen when a mass of air contracts?", "options": {"A": "The air remains at the same temperature", "B": "The air gets colder", "C": "The air gets warmer", "D": "The air moves faster"}, "answer": "B", "answer_raw": "B", "explanation": "Air is a gas. According to the gas laws, gasses will get colder when they contract.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 1, "flags": ["tag_fallback"], "page": 595, "excluded": false}, {"id": "MC-0171", "source_number": 1729, "subtest": "MC", "stem": "Which of the following would feel hottest at one end if the other end were placed over a fire?", "options": {"A": "A metal skewer", "B": "A wooden stick", "C": "A plastic rod", "D": "A rubber stick"}, "answer": "A", "answer_raw": "A", "explanation": "Of the four materials, metal is the best conductor of heat, so a metal skewer would feel the\nhottest.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 596, "excluded": false}, {"id": "MC-0172", "source_number": 1730, "subtest": "MC", "stem": "If you use a lever to lift a 200 pound weight with an effort of 40 pounds, with is the mechanical\nadvantage?", "options": {"A": "4", "B": "0.2", "C": "8,000", "D": "5"}, "answer": "D", "answer_raw": "D", "explanation": "Mechanical advantage = load/effort = 200/40 = 5", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "levers"], "difficulty": 2, "flags": [], "page": 596, "excluded": false}, {"id": "MC-0173", "source_number": 1731, "subtest": "MC", "stem": "Water flows into a container at a rate of 140 gallons per minute. The container has a small\nopening at the bottom that drains water at a rate of 1 gallon per second.\nHow long will it take to fill the container to 240 gallons?", "options": {"A": "2 min", "B": "3 min", "C": "4 min", "D": "Not enough information"}, "answer": "B", "answer_raw": "B", "explanation": "The opening drains water at 1 gallon/second which is equivalent to 60 gallons/min.\n\n\n\nTherefore, the net gain of water is 140 gallons/min - 60/gallons/min = 80 gallons/min.\nTo fill 240 gallons at a rate of 80 gallons/min will take 3 minutes.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage"], "difficulty": 2, "flags": ["tag_fallback"], "page": 596, "excluded": false}, {"id": "MC-0174", "source_number": 1732, "subtest": "MC", "stem": "Which of the following statements is true for water flowing from a 4 inch pipe to a smaller 2 inch\npipe?", "options": {"A": "The same amount of water passes through both the 4 inch pipe and the 2 inch pipe.", "B": "The pressure is greater in the 2 inch pipe.", "C": "More water passes through the 4 inch pipe than through the 2 inch pipe.", "D": "The pressure is lower in the 4 inch pipe."}, "answer": "A", "answer_raw": "A", "explanation": "Water cannot be compressed. Therefore, the same amount of water must be flowing through\nboth the 4 inch pipe and the 2 inch pipe.", "figure": null, "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": [], "page": 597, "excluded": false}, {"id": "MC-0175", "source_number": 1733, "subtest": "MC", "stem": "What is the mechanical advantage of this pulley system?", "options": {"A": "6", "B": "4", "C": "3", "D": "2"}, "answer": "C", "answer_raw": "C", "explanation": "In a pulley system, you calculate the mechanical advantage by counting up the number of\nsupporting ropes/ strands that support the weight.\nIn this case, there are 3 supporting strands that support the load, so the mechanical advantage\nis 3.", "figure": "assets/figures/q1733.jpg", "passage_id": null, "topics": ["pulleys", "mechanical_advantage"], "difficulty": 1, "flags": ["has_figure"], "page": 597, "excluded": false}, {"id": "MC-0176", "source_number": 1734, "subtest": "MC", "stem": "In the figure below, if gear A turns 15 times, how many revolutions will gear B make?", "options": {"A": "15 revolutions", "B": "5 revolutions", "C": "30 revolutions", "D": "45 revolutions"}, "answer": "D", "answer_raw": "D", "explanation": "Gear A has 18 teeth and gear B has 6 teeth.\nTherefore, for every 1 revolution of gear A, gear B will have 3 revolutions.", "figure": "assets/figures/q1734.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 1, "flags": ["has_figure"], "page": 598, "excluded": false}, {"id": "MC-0177", "source_number": 1735, "subtest": "MC", "stem": "Pulling on the rope at point A will lift the load.\nHow far will you have to pull the rope at point A to lift the load 15 feet?", "options": {"A": "15 feet", "B": "45 feet", "C": "30 feet", "D": "60 feet"}, "answer": "B", "answer_raw": "B", "explanation": "The mechanical advantage of the pulley is 3 since there are three ropes supporting the load.\nTherefore, the distance at point A needs to 3x or 3 \u00d7 15 = 45 ft.", "figure": "assets/figures/q1735.jpg", "passage_id": null, "topics": ["force_pressure"], "difficulty": 2, "flags": ["has_figure"], "page": 598, "excluded": false}, {"id": "MC-0178", "source_number": 1736, "subtest": "MC", "stem": "In the figure below, if gear 1 turns counterclockwise (as shown by the arrow), which of the gears\nwill also turn in the same direction?", "options": {"A": "2 and 4", "B": "2 and 3", "C": "3 and 4", "D": "4"}, "answer": "C", "answer_raw": "C", "explanation": "Gear 1 turns counterclockwise causing gear 2 to turn clockwise which results in gear 3 and 4 to\nturn counterclockwise.", "figure": "assets/figures/q1736.jpg", "passage_id": null, "topics": ["gears"], "difficulty": 2, "flags": ["has_figure"], "page": 599, "excluded": false}, {"id": "MC-0179", "source_number": 1737, "subtest": "MC", "stem": "In the pulley system below, how fast does pulley D rotate, if pulley A rotates at 50 rpm?", "options": {"A": "100 rpm", "B": "50 rpm", "C": "200 rpm", "D": "64 rpm"}, "answer": "C", "answer_raw": "C", "explanation": "A larger pulley causes a smaller pulley to rotate faster by the ratio of their diameters.\nIf pulley A rotates at 50 rpm, then pulley B rotates at 50 \u00d7 8/5=80 rpm.\nSince C is directly connected to B it rotates at the same rate (80 rpm).\nFinally, pulley D will rotate at 80 rpm x 10/4 = 200 rpm", "figure": "assets/figures/q1737.jpg", "passage_id": null, "topics": ["pulleys"], "difficulty": 2, "flags": ["has_figure"], "page": 600, "excluded": false}, {"id": "MC-0180", "source_number": 1738, "subtest": "MC", "stem": "Which of the following is an example of a Class 2 Lever?", "options": {"A": "Fishing rod", "B": "Bottle opener", "C": "See-Saw", "D": "Scissors"}, "answer": "B", "answer_raw": "B", "explanation": "A bottle opener is a single class 2 lever.\nA see-saw and scissors are class 1 levers.\nA Fishing rod is a class 3 lever.", "figure": "assets/figures/q1738.jpg", "passage_id": null, "topics": ["levers"], "difficulty": 1, "flags": ["has_figure"], "page": 601, "excluded": false}, {"id": "MC-0181", "source_number": 1739, "subtest": "MC", "stem": "Which of the following is not a type of simple machine?", "options": {"A": "Pulley", "B": "Spring", "C": "Lever", "D": "Screw"}, "answer": "B", "answer_raw": "B", "explanation": "The six types of simple machines are: pulley, lever, screw, wheel and axle, wedge, inclined\nplane.", "figure": null, "passage_id": null, "topics": ["springs", "pulleys", "levers"], "difficulty": 1, "flags": [], "page": 602, "excluded": false}, {"id": "MC-0182", "source_number": 1740, "subtest": "MC", "stem": "In the pulley system below, how fast does pulley D rotate, if pulley A rotates at 100 rpm?", "options": {"A": "25 rpm", "B": "50 rpm", "C": "100 rpm", "D": "12.5 rpm"}, "answer": "D", "answer_raw": "D", "explanation": "A larger pulley causes a smaller pulley to rotate faster by the ratio of their diameters.\nIf pulley A rotates at 100 rpm, then pulley B rotates at 100 \u00d7 4/10 = 40 rpm.\nSince C is directly connected to B it rotates at the same rate (40 rpm).\nFinally, pulley D will rotate at 40 rpm \u00d7 5/16 = 12.5 rpm", "figure": "assets/figures/q1740.jpg", "passage_id": null, "topics": ["pulleys"], "difficulty": 2, "flags": ["has_figure"], "page": 603, "excluded": false}, {"id": "MC-0183", "source_number": 1741, "subtest": "MC", "stem": "What weight (X) is needed to balance the two loads shown in the figure below?", "options": {"A": "15 lbs", "B": "10 lbs", "C": "5 lbs", "D": "7.5 lbs"}, "answer": "B", "answer_raw": "B", "explanation": "For the weights to balance, the sum of the forces must balance.\nTherefore, (5 lbs \u00d7 8 ft) + (10 lbs \u00d7 4 ft) = X lbs \u00d7 8 ft or 40 lb-ft + 40 lb-ft =8X lb-ft or X=10 lbs", "figure": "assets/figures/q1741.jpg", "passage_id": null, "topics": ["force_pressure", "center_of_gravity"], "difficulty": 1, "flags": ["has_figure"], "page": 603, "excluded": false}, {"id": "MC-0184", "source_number": 1742, "subtest": "MC", "stem": "The diagram below represents a load sliding down an incline.\nWhich of the forces (A,B,C, or D) represent friction?", "options": {"A": "A", "B": "B", "C": "C", "D": "D"}, "answer": "D", "answer_raw": "D", "explanation": "Friction is represented by the force the resists the load moving down the hill.", "figure": "assets/figures/q1742.jpg", "passage_id": null, "topics": ["force_pressure", "friction"], "difficulty": 2, "flags": ["has_figure"], "page": 604, "excluded": false}, {"id": "MC-0185", "source_number": 1743, "subtest": "MC", "stem": "On a bicycle there are 30 teeth on the gear sprocket connected to the pedals, and 10 teeth on\nthe sprocket connected to the rear wheels.\nIf you pedal the bike 12 times, how many times will the rear wheel turn?", "options": {"A": "4 times", "B": "12 times", "C": "24 times", "D": "36 times"}, "answer": "D", "answer_raw": "D", "explanation": "Since there are 30 teeth on the pedal sprocket, but only 10 teeth on the rear wheel, each\nrevolution of the pedal will turn the rear wheel 3 times.\nSo 12 revolutions will turn the rear wheel 36 times.", "figure": null, "passage_id": null, "topics": ["gears"], "difficulty": 2, "flags": [], "page": 605, "excluded": false}, {"id": "MC-0186", "source_number": 1744, "subtest": "MC", "stem": "An axe is an example of what type of simple machine.", "options": {"A": "Lever", "B": "Inclined plane", "C": "Wedge", "D": "None of the above"}, "answer": "C", "answer_raw": "C", "explanation": "An axe is a classic example of a wedge.", "figure": null, "passage_id": null, "topics": ["mechanical_advantage", "levers"], "difficulty": 1, "flags": [], "page": 605, "excluded": false}, {"id": "MC-0187", "source_number": 1745, "subtest": "MC", "stem": "When a football is thrown upwards in the air, what causes it to arc back towards the ground?", "options": {"A": "Centrifugal force", "B": "Gravity", "C": "Friction", "D": "Wind resistance"}, "answer": "B", "answer_raw": "B", "explanation": "Gravity is the force that causes objects to be pulled back towards the earth.\n\n\n\nSection 9: Assembling Objects", "figure": null, "passage_id": null, "topics": ["friction", "force_pressure"], "difficulty": 2, "flags": [], "page": 605, "excluded": false}];
})(typeof self !== "undefined" ? self : this);
